// Plan 51 / Migration 189 (Koordinator 31.10.2026): Buchungen ohne Preis zeigen „Kosten unbekannt“ statt 0 €; Summen mit einem unbekannten Teil zeigen den
// bekannten Betrag mit dem Zusatz „dazu N Aufrufe ohne Preis (Kosten unbekannt)“. ohne_preis/aufrufe kommen aus der Datenbank (Migration 189).
const KU_n = x => Math.max(0, Number((x || {}).ohne_preis) || 0);
const KU_alle = x => KU_n(x) > 0 && KU_n(x) >= (Number((x || {}).aufrufe) || 0);
const KU_t = n => n.toLocaleString('de-DE') + (n === 1 ? ' Aufruf' : ' Aufrufe') + ' ohne Preis';
const KU_dazu = n => 'dazu ' + KU_t(n) + ' (Kosten unbekannt)';
const KU_wert = (x, betrag) => KU_alle(x) ? 'Kosten unbekannt (' + KU_t(KU_n(x)) + ')' : KU_n(x) ? betrag + ' · ' + KU_dazu(KU_n(x)) : betrag;
// Talent-Profil (ALLY 25, BA5, Stefan 19.10.2026): Kopf mit Zeitraum, Überblick (Kennzahlen, Accounts, Termine und Deadlines), Abschnitte Performance, Content,
// Audience, Kampagnen, Daten und Notizen. Daten wie ALLY 8 (talents_talent, talents_beitraege, talents_notizen, talents_kampagnen, talent_json).
// Formulare mit den Aktionsnamen und Feldern von ALLY 8 (tl_*, tn_*). Liefert nur die Seitenbeschreibung (JSON).
// BA6 (Migration 61): Abschnitt „Aufgaben, Termine und Erinnerungen“ (talents_aufgaben_ui, Aktionen kp_aufgabe_*), „Nächste Termine und Deadlines“ aus Aufgaben und Deliverables.
// BA7 (Migration 62): Abschnitt „Talent-Bereich“ (talent_zugang_ui, Aktionen tz_*): Zugang für das Talent (Zugangslink zum Kopieren, kein Mailversand), Briefing, Sichtbarkeit;
// nur für Admin und die zuständige Person aus dem Management.
// BA8 (Migration 63): Mit eingestelltem Absender-Postfach (mail_aktiv) geht der Zugangslink zusätzlich per Mail (tz_link_senden = erneut senden);
// Kalender-Abo des Talents (seit, letzter Abruf; ohne Adresse) mit „Abo beenden“ (tz_kalender_widerrufen).
// Migration 64 (Rollenverwaltung): Talent-Bereich für alle mit dem Recht „Talent-Zugang und Talent-Bereich einstellen“ für dieses Talent; Schalter Screenshot-Upload
// (zeige_upload, mit_upload); „Ordner im Speicherort“ (talent_ordner_ui, to_freigeben, to_beenden; Freigeben nur mit Recht am Speicherort, nichts wird gelöscht).
// Migration 65 (Stefan 20.10.2026, 09:23/09:26): Filter „Manuelle Daten“ im Kopf; Zahlen mit manuellen Daten ohne Doppelzählung; Abschnitt „Doppelte Daten prüfen“
// (talents_doppelt_ui; beide Werte nebeneinander, Entscheidung tz_dd_automatisch / tz_dd_manuell mit talent_id und doppelt_id, Verlauf); i-Symbol je Account mit der
// Info, welche Daten die Verbindung liefert (talents_verbindung_info).
// BA9 (Migration 68): Unterabschnitt „Ally-Chat“ im Talent-Bereich (talent_chat_ui): ein- und ausschalten (tz_chat_an, tz_chat_aus), Chat-Anmeldename, KI-Verbrauch des Monats;
// KI-Grenze je Talent nur für Admins (tz_ki_grenze). Kein Knopf „Chat öffnen“ (Chat nur über die App Element).
// Migration 67: „Ordner im Speicherort“ durchsuchen (ob=1, op), Ordner anlegen (so_anlegen) und umbenennen (so_umbenennen, ou) über SPEICHER 1 und direkt freigeben
// (to_freigeben). Daten aus „Daten laden“, Ordnerliste aus „Ordner lesen (SPEICHER 1)“, nur wenn er lief. Gelöscht wird nichts.
const E = $('Start').first().json;
const D = $('Daten laden').first().json || {};
const lief = n => { try { return $(n).isExecuted; } catch (e) { return false; } };
const OL = lief('Ordner lesen (SPEICHER 1)') ? ($('Ordner lesen (SPEICHER 1)').first().json || null) : null;
const OPZ = (lief('Parameter') ? $('Parameter').first().json.ordner : null) || {};
const P = E.parameter || {};
const T = D.t || {};
const krumen0 = [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: 'Dashboard', ziel: { seite: 'talents' } }];
if (T.ok !== true) {
  const titel = 'Talent-Profil';
  return [{ json: { inhalt: { seite: { schluessel: 'talent', art: 'funktion', titel, krumen: krumen0.concat([{ text: titel }]) },
    bloecke: [{ typ: 'hinweis', ton: 'warn', text: String(T.fehler || 'Dieses Talent gibt es nicht oder es ist für dich nicht freigeschaltet.') }, { typ: 'aktion', text: 'Zum Dashboard', ziel: { seite: 'talents' } }] } } }];
}
// verw: dieses Talent verwalten (Stammdaten, Einladungslink, Accounts trennen, archivieren): „Talents verwalten“ alle, Management die eigenen Talents (talents_ui_rechte, Stefan 20.10.2026)
const TA = T.talent || {}, id = Number(TA.id), J = D.j || null, verw = T.darf_verwalten === true || (D.r && D.r.talent === true);
const name = String(TA.anzeigename || TA.name || ('Talent ' + id));
const worte = name.split(/\s+/).filter(Boolean);
const avatar = ((worte[0] || '').charAt(0) + (worte.length > 1 ? worte[worte.length - 1].charAt(0) : (worte[0] || '').charAt(1))).toUpperCase();
const kan = Array.isArray(T.kanaele) ? T.kanaele : [];
const hier = (anker, extra) => ({ seite: 'talent', parameter: Object.assign({ id }, P.zeitraum ? { zeitraum: P.zeitraum } : {}, P.von ? { von: P.von } : {}, P.bis ? { bis: P.bis } : {}, P.kanal ? { kanal: P.kanal } : {},
  P.manuell === '0' ? { manuell: '0' } : {}, extra || {}), anker });
const zust = (TA.zustaendig || []).map(p => String(p.name || '')).join(', ');
const kopf = { schluessel: 'talent', art: 'funktion', titel: name, avatar,
  beschreibung: [kan.map(k => k.text && k.text.startsWith('@') ? k.text : '').filter(Boolean)[0], kan.map(k => String(k.name || '')).filter((x, i, a) => x && a.indexOf(x) === i).join(', '),
    zust ? 'Manager/in: ' + zust : ''].filter(Boolean).join(' · ') + (TA.archiviert ? ' · archiviert' : ''),
  krumen: krumen0.concat([{ text: name }]),
  zahnrad: { ziel: { seite: 'einstellungen', parameter: { bereich: 'talents' } }, label: 'Einstellungen für Talents' } };
// Plan 62 (K5, Regel „nichts doppelt“; Entscheidung Stefan über den Koordinator 01.11.2026): „Report erstellen“ steht nur noch in der Kachel „Reports“
// („Seite ergänzen“, Schritt Download-Links), keine Hauptaktion im Kopf. Zahnrad und übrige Knöpfe bleiben.
const zr = T.zeitraum || {}, F0 = T.filter || {};
// 7a–7c (Stefan 24.10.2026, 16:52/16:54, freigegeben 16:55): Zeitraum als Ausklappliste, Account als Ausklappliste, „Manuelle Daten einbeziehen“ als Häkchen – wie auf Talents; Reihe über Regel filterReihe
kopf.filter = { id: 'zeitraum', label: 'Zeitraum', felder: [{ typ: 'auswahl', name: 'zeitraum', label: 'Zeitraum', ausklappliste: true, wert: String(F0.zeitraum || '28tage'),
  optionen: (T.zeitraeume || []).map(z => ({ wert: z.schluessel, text: String(z.name || '') })) }].concat(F0.zeitraum === 'frei' ? [
  { typ: 'datum', name: 'von', label: 'Von', wert: String(F0.von || '') }, { typ: 'datum', name: 'bis', label: 'Bis', wert: String(F0.bis || '') }] : [])
  // 7d (Stefan 24./25.10.2026): Account als Mehrfachauswahl mit Häkchen; nichts gewählt = „Alle Accounts“, ein Sammeleintrag („Instagram (alle Accounts)“) umfasst die Accounts seiner Plattform
  .concat((T.kanal_auswahl || []).length > 1 ? [{ typ: 'mehrfach', liste: true, name: 'kanal', label: 'Account', platzhalter: 'Alle Accounts', einheit: 'Accounts',
    // S2 (Prüfung M152): eine Plattform mit genau einem Account (ohne eigenen Eintrag in der Liste) erscheint als dieser Account, nicht als „Alle Accounts“
    wert: String(F0.kanal || '').split(',').filter(Boolean).map(s => { const KA = T.kanal_auswahl || []; if (KA.some(k => k.schluessel === s)) return s;
      const eins = KA.filter(k => k.kanal_id && k.plattform === s); return eins.length === 1 ? eins[0].schluessel : s; }),
    // plattform und kurz für die Zeile unter der Filterreihe (Symbol statt Plattformname; Sammeleintrag = „alle Accounts“)
    optionen: (T.kanal_auswahl || []).map(k => ({ wert: k.schluessel, text: String(k.name || ''), plattform: String(k.plattform || ''),
      kurz: k.alle ? 'alle Accounts' : k.kanal_id ? String(k.name || '').replace(/^\S+\s+/, '') : String(k.name || ''),
      umfasst: k.alle ? (T.kanal_auswahl || []).filter(x => x.kanal_id && x.plattform === k.plattform).map(x => x.schluessel) : undefined })) }] : [])
  // Migration 65: manuelle Daten einbeziehen (Standard) oder nur automatisch geladene Zahlen
  .concat([{ typ: 'haken', name: 'manuell', label: 'Manuelle Daten einbeziehen', wert: F0.manuell === '0' ? '0' : '1', wert_an: '1', wert_aus: '0',
    info: 'Manuelle Daten sind Zahlen aus einem manuellen Import von Insights, die geprüft und bestätigt wurden. Ist die Option deaktiviert, werden ausschließlich automatisch geladene Zahlen berücksichtigt.' }]) };
const A = D.a && D.a.ok === true ? D.a : null;
const aktionen = (A ? [{ text: 'Aufgabe, Termin oder Erinnerung', ziel: hier('a-aufgaben') }] : []).concat([{ text: 'Notiz anlegen', fenster: 'notiz' }]);
if (verw && J) aktionen.unshift({ text: 'Stammdaten', fenster: 'stammdaten' });
if (verw && !TA.archiviert) aktionen.push({ text: 'Archivieren', aktion: 'tl_talent_archivieren', werte: { id }, frage: name + ' archivieren? Die Zahlen bleiben erhalten, es werden keine neuen abgerufen.' });
if (verw && TA.archiviert) aktionen.push({ text: 'Reaktivieren', aktion: 'tl_talent_reaktivieren', werte: { id } });
kopf.aktionen = aktionen;

// ---------- Überblick ----------
const KZ = {}; for (const k of (T.kennzahlen || [])) KZ[k.schluessel] = k;
const kz = (s, label) => { const k = KZ[s] || {}; const v = k.veraenderung || {}, zu = k.zuwachs || {};
  return { label: label || String(k.name || s), wert: String(k.text || '–'), neben: v.prozent !== null && v.prozent !== undefined && v.text ? String(v.text) : (zu.wert !== null && zu.wert !== undefined && zu.text ? String(zu.text) : '') }; };
const kennzahlen = [kz('follower', 'Follower'), kz('reichweite', 'Reichweite'), kz('interaktionen', 'Interaktionen'),
  { label: 'Beiträge', wert: String(T.anzahl_beitraege ?? '–'), neben: String(zr.name || '') }];
const JK = {}; for (const k of ((J && J.kanaele) || [])) JK[k.kanal_id] = k;
const warn = {}; for (const w of (T.warnungen || [])) (warn[w.kanal_id] = warn[w.kanal_id] || []).push(w);
const accounts = kan.map(k => {
  const w = (warn[k.kanal_id] || [])[0];
  const e = { marke: w ? { text: w.stufe === 'warnung' ? 'prüfen' : 'Hinweis', ton: w.stufe === 'warnung' ? 'warn' : 'grau' } : { text: String(k.status_text || k.status || ''), ton: k.status === 'verbunden' ? 'ok' : 'grau' },
    text: String(k.name || '') + (k.text && k.text !== k.name ? ' ' + k.text : ''), neben: w ? String(w.text || '') : (k.gueltig_bis ? 'gültig bis ' + k.gueltig_bis : '') };
  if (verw && JK[k.kanal_id] && JK[k.kanal_id].darf_trennen) e.aktion = { text: 'Trennen', aktion: 'tl_kanal_trennen', werte: { id, kanal_id: k.kanal_id }, frage: String(k.name || '') + ' ' + String(k.text || '') + ' trennen?' };
  return e;
});
if (J && J.einladung && J.einladung.gueltig_bis) accounts.push(Object.assign({ marke: { text: J.einladung.abgelaufen ? 'abgelaufen' : 'Einladung', ton: J.einladung.abgelaufen ? 'warn' : 'grau' },
  text: 'Einladungslink', neben: 'gültig bis ' + J.einladung.gueltig_bis }, verw ? { aktion: { text: 'Neuer Link', aktion: 'tl_einladung_neu', werte: { id } } } : {}));
else if (verw && kan.some(k => k.status !== 'verbunden')) accounts.push({ text: 'Einladungslink für offene Accounts', aktion: { text: 'Neuer Link', aktion: 'tl_einladung_neu', werte: { id } } });
const KA = (D.k || {}).zeilen || [];
const termine = KA.filter(k => k.status !== 'beendet').sort((a, b) => String(a.bis_iso || '').localeCompare(String(b.bis_iso || ''))).slice(0, 6)
  .map(k => ({ marke: { text: k.status === 'laufend' ? 'Ende ' + String(k.bis || '').slice(0, 6) : 'Start ' + String(k.von || '').slice(0, 6), ton: k.talents_ohne_beitrag ? 'warn' : '' },
    text: String(k.titel || k.name || ''), neben: k.talents_ohne_beitrag ? k.talents_ohne_beitrag + ' ohne Beitrag' : String(k.status_text || '') }));
const termineNeu = A ? (A.naechste || []).map(x => ({ marke: { text: String(x.marke || ''), ton: x.warn ? 'warn' : '' }, text: String(x.text || ''), neben: String(x.neben || ''),
  ziel: x.kampagne_id ? { seite: 'kampagnen', parameter: { kampagne: x.kampagne_id } } : hier('a-aufgaben', x.aufgabe_id ? { f: 'a-' + x.aufgabe_id } : {}), ziel_text: x.kampagne_id ? 'Kampagne' : 'Öffnen' })) : null;
// Migration 65: i-Symbol am Überblick (manuelle Daten in den Zahlen) und an der Karte Accounts (welche Daten jede Verbindung liefert)
const MAN = T.manuell || {}, VI = D.vi || {}, VIK = VI.kanaele || {};
const ubInfo = MAN.zaehlen === false ? ['Ohne manuelle Daten: nur automatisch geladene Zahlen.']
  : Number(MAN.gezaehlt) > 0 ? ['Enthält ' + MAN.gezaehlt + (Number(MAN.gezaehlt) === 1 ? ' bestätigten manuellen Wert' : ' bestätigte manuelle Werte') + ' (' + String(MAN.gezaehlt_text || '').replace(/^manuell: /, '') + ').'] : [];
if (Number(MAN.doppelt_offen) > 0) ubInfo.push({ text: MAN.doppelt_offen + (Number(MAN.doppelt_offen) === 1 ? ' Wert überschneidet sich' : ' Werte überschneiden sich') + ' mit automatischen Zahlen; bis zur Entscheidung zählt der automatische Wert („Doppelte Daten prüfen“).', ton: 'warn' });
const accInfo = kan.filter(k => VIK[String(k.kanal_id)]).map(k => String(k.name || '') + (k.text && k.text !== k.name ? ' ' + k.text : '') + ': ' + String(VIK[String(k.kanal_id)]));
const ueberblick = { kennzahlen, info: ubInfo.length ? ubInfo : undefined, karten: [{ titel: 'Accounts', leer: 'Keine Accounts.', eintraege: accounts, info: accInfo.length ? accInfo : undefined },
  { titel: 'Nächste Termine und Deadlines', leer: 'Keine anstehenden Termine.', eintraege: termineNeu || termine }] };

// ---------- Performance ----------
const tage = ((T.verlauf || {}).tage || []);
const perf = [];
if (tage.some(t => t.reichweite !== null && t.reichweite !== undefined)) perf.push({ typ: 'unterueberschrift', text: 'Reichweite je Tag' },
  { typ: 'grafik', art: 'saeulen', werte: tage.map(t => Number(t.reichweite) || 0), beschreibung: 'Reichweite je Tag, ' + String(zr.text || '') });
if (!perf.length) perf.push({ typ: 'text', ton: 'grau', text: 'Noch keine Zahlen in diesem Zeitraum.' });
if (T.datenstand && T.datenstand.text) perf.push({ typ: 'text', ton: 'grau', text: String(T.datenstand.text) });
const abschnitte = [{ id: 'performance', titel: 'Performance', zahl: String(zr.name || ''), offen_standard: true, inhalt: perf }];

// ---------- Aufgaben, Termine und Erinnerungen (BA6) ----------
const KAN = [{ wert: 'bereich', text: 'Talent-Bereich' }, { wert: 'kalender', text: 'Kalender des Talents' }, { wert: 'mail', text: 'Mail' }];
const ARTEN = [{ wert: 'aufgabe', text: 'Aufgabe' }, { wert: 'review', text: 'Review zu Content' }, { wert: 'termin', text: 'Termin' }, { wert: 'erinnerung', text: 'Erinnerung' }];
const aufgabenFenster = [];
if (A) {
  const AZ = A.zeilen || [];
  const kOpt = [{ wert: '', text: 'ohne Kampagne' }].concat((A.kampagnen || []).map(x => ({ wert: String(x.id), text: String(x.titel || '') })));
  const dOpt = [{ wert: '', text: 'ohne Deliverable' }].concat((A.deliverables || []).map(x => ({ wert: String(x.id), text: String(x.text || '') })));
  const inhaltA = [{ typ: 'filter', id: 'aufgaben', label: 'Aufgaben filtern', felder: [{ typ: 'auswahl', name: 'astatus', label: 'Status', wert: String(A.status || 'offen'),
      optionen: [{ wert: 'offen', text: 'offen' }, { wert: 'erledigt', text: 'erledigt und abgesagt' }, { wert: 'alle', text: 'alle' }] }] },
    { typ: 'tabelle', id: 'aufgaben', titel: 'Aufgaben, Termine und Erinnerungen', spalten: [{ schluessel: 'wann', titel: 'Wann', sortierbar: true }, { schluessel: 'art', titel: 'Art', sortierbar: true },
      { schluessel: 'titel', titel: 'Was', sortierbar: true }, { schluessel: 'bezug', titel: 'Bezug' }, { schluessel: 'an', titel: 'Senden an' }, { schluessel: 'status', titel: 'Status', sortierbar: true },
      { schluessel: 'aktion', titel: 'Aktion' }],
      zeilen: AZ.map(a => ({ zellen: { wann: a.wann_text ? { marke: { text: String(a.wann_text), ton: a.status === 'offen' && a.heute_oder_frueher ? 'warn' : '' } } : '–',
        art: { marke: { text: String(a.art_text || ''), ton: a.art === 'review' ? 'warn' : a.art === 'termin' ? '' : 'grau' } }, titel: { text: String(a.titel || ''), fenster: 'a-' + a.id },
        bezug: a.kampagne_id ? { text: String(a.deliverable || a.kampagne || ''), ziel: { seite: 'kampagnen', parameter: { kampagne: a.kampagne_id } }, neben: a.deliverable ? String(a.kampagne || '') : String(a.quelle_text || '') }
          : String(a.quelle_text || ''),
        an: String(a.kanaele_text || '') + (a.mail_text ? ' · ' + a.mail_text : ''), status: { marke: { text: String(a.status_text || ''), ton: a.status === 'offen' ? '' : a.status === 'erledigt' ? 'ok' : 'grau' }, neben: String(a.erledigt_text || '') },
        aktion: a.status === 'offen' ? { aktion: { text: a.art === 'termin' ? 'Absagen' : 'Erledigt', aktion: a.art === 'termin' ? 'kp_aufgabe_absagen' : 'kp_aufgabe_erledigt', werte: { id: a.id },
          frage: a.art === 'termin' ? 'Termin „' + String(a.titel || '') + '“ absagen?' : undefined } } : { aktion: { text: 'Wieder offen', aktion: 'kp_aufgabe_offen', werte: { id: a.id } } } } })),
      sortierung: A.sortierung || {}, seite: Number(A.seite) || 1, je_seite: 20, gesamt: Number(A.anzahl) || 0,
      leer: A.status === 'offen' ? 'Keine offenen Aufgaben, Termine oder Erinnerungen.' : 'Keine Einträge.' },
    { typ: 'formular', id: 'aufgabe-neu', aktion: 'kp_aufgabe_neu', titel: 'Neu', werte: { talent_id: id, kanaele_sichtbar: '1' }, spalten: 4, felder: [
      { typ: 'auswahl', name: 'art', label: 'Art', wert: 'aufgabe', optionen: ARTEN }, { typ: 'text', name: 'titel', label: 'Was', pflicht: true, platzhalter: 'z. B. Reel hochladen' },
      { typ: 'datum_zeit', name: 'wann', label: 'Wann' }, { typ: 'auswahl', name: 'kampagne_id', label: 'Kampagne', wert: '', optionen: kOpt },
      { typ: 'mehrfach', name: 'kanaele', label: 'Senden an', wert: ['bereich'], optionen: KAN, breite: 'voll', info: 'Ohne Auswahl nur intern. Kalender und Mail werden mit dem Kalender-Abo bzw. dem Absender-Postfach zugestellt.' },
      { typ: 'textbereich', name: 'text', label: 'Details', zeilen: 2, breite: 'voll' }], knoepfe: [{ text: 'Anlegen' }] }];
  abschnitte.push({ id: 'aufgaben', titel: 'Aufgaben, Termine und Erinnerungen', zahl: (Number(A.offen) || 0) + ' offen', offen_standard: true, inhalt: inhaltA });
  for (const a of AZ) aufgabenFenster.push({ id: 'a-' + a.id, art: 'seitenfenster', titel: String(a.titel || ''), untertitel: String(a.art_text || ''), schliessen_ziel: hier('a-aufgaben'), inhalt: [
    { typ: 'paare', eintraege: [['Art', a.art_text], ['Wann', a.wann_text || '–'], a.ort ? ['Ort', a.ort] : null, ['Senden an', a.kanaele_text], a.mail_text ? ['Mail', a.mail_text] : null,
      ['Status', a.status_text + (a.erledigt_text ? ' (' + a.erledigt_text + ')' : '')], a.kampagne ? ['Kampagne', a.kampagne] : null, a.deliverable ? ['Deliverable', a.deliverable] : null,
      a.quelle_text ? ['Herkunft', a.quelle_text] : null, a.text ? ['Details', a.text] : null].filter(Boolean).map(p => ({ label: p[0], wert: String(p[1] ?? '') })) },
    { typ: 'formular', id: 'aufgabe-' + a.id, aktion: 'kp_aufgabe_aendern', titel: 'Bearbeiten', werte: { id: a.id, kanaele_sichtbar: '1', ganztags_sichtbar: '1' }, spalten: 2, felder: [
      { typ: 'auswahl', name: 'art', label: 'Art', wert: a.art, optionen: ARTEN }, { typ: 'text', name: 'titel', label: 'Was', pflicht: true, wert: String(a.titel || '') },
      { typ: 'datum_zeit', name: 'wann', label: 'Wann', wert: String(a.wann_iso || '') }, { typ: 'datum_zeit', name: 'ende', label: 'Ende (Termin)', wert: String(a.ende_iso || '') },
      { typ: 'text', name: 'ort', label: 'Ort', wert: String(a.ort || '') }, { typ: 'auswahl', name: 'kampagne_id', label: 'Kampagne', wert: a.kampagne_id ? String(a.kampagne_id) : '', optionen: kOpt },
      { typ: 'auswahl', name: 'deliverable_id', label: 'Deliverable', wert: a.deliverable_id ? String(a.deliverable_id) : '', optionen: dOpt, breite: 'voll' },
      { typ: 'mehrfach', name: 'kanaele', label: 'Senden an', wert: (a.kanaele || []).map(String), optionen: KAN, breite: 'voll' },
      { typ: 'haken', name: 'ganztags', label: 'Ganztägig (Termin)', an: a.ganztags === true, breite: 'voll' },
