// ---------- Doppelte Daten prüfen (Migration 65, Stefan 20.10.2026, 09:26) ----------
const DD = D.dd && D.dd.ok === true ? D.dd : null;
const ddFenster = [];
if (DD && Number(DD.anzahl) > 0) {
  const E2 = Array.isArray(DD.eintraege) ? DD.eintraege : [];
  const wer = x => String(x.plattform_name || '') + (x.konto ? ' ' + x.konto : (x.accounts ? ' ' + x.accounts : ''));
  // „Alle anzeigen“ (Stefan 21.10.2026): blättern je 20 (Seite aus ?p=doppelt:n) statt nach 20 abzuschneiden; Fenster nur für die Zeilen der Seite
  const ddSeite = Math.min(Math.max(1, Math.ceil(E2.length / 20)), Math.max(1, Number((E.seiten || {}).doppelt) || 1)), ddTeil = E2.slice((ddSeite - 1) * 20, ddSeite * 20);
  const zeilenDD = ddTeil.map(x => ({ zellen: {
    wert: { text: String(x.kennzahl_name || ''), neben: wer(x) }, zeitraum: String(x.zeitraum_text || ''),
