    aktion: { text: x.status === 'offen' && x.darf ? 'Entscheiden' : 'Ansehen', fenster: 'dd-' + x.id } } }));
  for (const x of ddTeil) {
    const ent = x.entscheidung || null;
    const inhalt = [{ typ: 'paare', eintraege: [['Account', wer(x)], ['Kennzahl', x.kennzahl_name], ['Zeitraum', x.zeitraum_text], ['Automatisch geladen', x.auto_text],
      ['Manuell', x.manuell_text], ['Quelle', x.quelle_text], ['Stand', x.status_text],
      ent ? ['Entschieden', String(ent.text || '') + ' – ' + String(ent.von || '') + ', ' + String(ent.am || '') + (ent.gueltig === false ? ' (gilt nicht mehr)' : '')] : null]
      .filter(p => p && p[1] !== undefined && p[1] !== null && String(p[1]) !== '').map(p => ({ label: p[0], wert: String(p[1]) })) },
      { typ: 'text', ton: x.status === 'offen' ? 'warn' : 'grau', text: String(x.zaehlt_text || '') }];
    if (x.darf) {
