    ddFenster.push({ id: 'dd-' + x.id, art: 'dialog', titel: 'Doppelte Daten: ' + String(x.kennzahl_name || ''), untertitel: wer(x) + ' · ' + String(x.zeitraum_text || ''),
      info: String(DD.info || ''), inhalt });
  }
  abschnitte.push({ id: 'doppelte-daten', titel: 'Doppelte Daten prüfen', zahl: Number(DD.offen) > 0 ? DD.offen + ' offen' : String(DD.anzahl), offen_standard: Number(DD.offen) > 0,
    info: String(DD.info || ''), inhalt: [{ typ: 'tabelle', id: 'doppelt', titel: 'Doppelte Daten',
      spalten: [{ schluessel: 'wert', titel: 'Kennzahl' }, { schluessel: 'zeitraum', titel: 'Zeitraum' }, { schluessel: 'auto', titel: 'Automatisch', ausrichtung: 'rechts' },
        { schluessel: 'manuell', titel: 'Manuell', ausrichtung: 'rechts' }, { schluessel: 'stand', titel: 'Stand' }, { schluessel: 'aktion', titel: 'Aktion' }],
      zeilen: zeilenDD, sortierung: {}, seite: ddSeite, je_seite: 20, gesamt: E2.length, leer: 'Keine doppelten Daten.' }] });
}
