}

// ---------- Fenster ----------
const fenster = [];
if (N.darf_schreiben) fenster.push({ id: 'notiz', art: 'dialog', titel: 'Notiz anlegen', inhalt: [{ typ: 'formular', id: 'notiz', aktion: 'tn_neu', werte: { talent_id: id },
  felder: [{ typ: 'textbereich', name: 'text', label: 'Notiz', pflicht: true, zeilen: 5, breite: 'voll' }], knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Speichern' }] }] });
for (const x of (N.notizen || [])) if (x.darf_bearbeiten) fenster.push({ id: 'notiz-' + x.id, art: 'dialog', titel: 'Notiz bearbeiten', inhalt: [{ typ: 'formular', id: 'notiz-' + x.id, aktion: 'tn_bearbeiten',
