  knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Speichern' }] }] });
if (verw && J) {
  const pl = []; for (const k of (J.kanaele || [])) if (k.status !== 'getrennt' && !pl.includes(k.plattform)) pl.push(k.plattform);
  const PLN = { instagram: 'Instagram', tiktok: 'TikTok', youtube: 'YouTube', facebook: 'Facebook', threads: 'Threads', pinterest: 'Pinterest', linkedin: 'LinkedIn' };
  fenster.push({ id: 'stammdaten', art: 'seitenfenster', titel: 'Stammdaten', untertitel: name, avatar, inhalt: [{ typ: 'formular', id: 'stammdaten', aktion: 'tl_talent_bearbeiten', werte: { id }, felder: [
    { typ: 'text', name: 'name', label: 'Name', wert: String(J.name || '') }, { typ: 'text', name: 'kuenstlername', label: 'Künstlername', wert: String(J.kuenstlername || '') },
    { typ: 'email', name: 'email', label: 'E-Mail-Adresse', wert: String(J.email || '') },
    // Zuständige Personen wählen nur mit „Talents verwalten“ (personen); Management bleibt selbst zuständig
    ...(Array.isArray(D.personen) ? [{ typ: 'mehrfach', name: 'personen', label: 'Manager/in', wert: (J.zustaendig || []).map(p => String(p.id)), optionen: D.personen.map(p => ({ wert: p.id, text: String(p.name || '') })) }] : []),
    { typ: 'mehrfach', name: 'kanaele', label: 'Accounts', wert: pl, optionen: Object.keys(PLN).filter(k => pl.includes(k) || ['instagram', 'tiktok', 'youtube'].includes(k)).map(k => ({ wert: k, text: PLN[k] })) },
    { typ: 'text', name: 'verfolgung_tage', label: 'Beiträge verfolgen (Tage)', wert: J.verfolgung_tage === null || J.verfolgung_tage === undefined ? '' : String(J.verfolgung_tage), hinweis: 'Leer = Standard der Agentur, „unbegrenzt“ möglich.' },
    { typ: 'textbereich', name: 'notiz', label: 'Notiz', wert: String(J.notiz || ''), zeilen: 3 }],
    schliessen_ziel: hier(), knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Speichern' }] }] });
}
return [{ json: { inhalt: { seite: kopf, ueberblick, abschnitte, fenster: fenster.concat(aufgabenFenster, ddFenster) } } }];

// Parameter (ALLY 25, Talent-Profil): Sitzung, Talent (nur Ziffern), Zeitraum-Filter wie ALLY 8 (zeitraum, von, bis, kanal; prüft die Datenbank),
// Sortierung des Contents (Spalte aus dem gespeicherten Zustand wird erst in "Seite beschreiben" gelesen, hier nur aus der Adresse ?s=), Seiten von Content und Notizen.
// Migration 65: manuell (Filter manuelle Daten).
// Migration 67: Ordner im Speicherort durchsuchen (ob=1, op = Pfad im Inhalte-Ordner, ou = Ordner zum Umbenennen); geprüft wird in der Datenbank und in SPEICHER 1.
// BA6: Aufgaben, Termine und Erinnerungen (Filter astatus = offen|erledigt|alle, Seite der Tabelle aufgaben; Sortierung aus dem Zustand in „Daten laden“).
const E = $input.first().json;
const P = E.parameter || {};
const S = E.seiten || {};
const id = /^[0-9]{1,9}$/.test(String(P.id || '')) ? String(P.id) : '';
const f = {};
if (/^(7tage|28tage|monat|vormonat|frei)$/.test(String(P.zeitraum || ''))) f.zeitraum = String(P.zeitraum);
for (const k of ['von', 'bis']) if (/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(P[k] || ''))) f[k] = String(P[k]);
// 7d (Stefan 24.10.2026): Account als Mehrfachauswahl, Liste aus bis zu 20 Schlüsseln, durch Komma getrennt; die Datenbank bereinigt (talents_kanal_filter)
if (/^([a-z_]{1,20}|k[0-9]{1,9})(,([a-z_]{1,20}|k[0-9]{1,9})){0,19}$/.test(String(P.kanal || ''))) f.kanal = String(P.kanal);
// Migration 65 (Stefan 20.10.2026, 09:23): Filter „Manuelle Daten“ (0 = nicht einbeziehen; Standard einbeziehen, prüft die Datenbank)
if (P.manuell === '0' || P.manuell === '1') f.manuell = String(P.manuell);
// Migration 77 (Stefan 21.10.2026, „Alle anzeigen“ zeigt alles): Zielgruppe mit allen Einträgen je Gruppe (Vorschau macht der Baukasten)
f.zielgruppe = 'alle';
const n = v => Math.min(500, Math.max(1, Number(v) || 1));
const af = { status: ['offen', 'erledigt', 'alle'].includes(String(P.astatus || '')) ? String(P.astatus) : 'offen', seite: String(n(S.aufgaben)),
  // Migration 77: alle nächsten Termine und Deadlines (statt höchstens 6) und Seite der Kampagnen-Tabelle (?p=kampagnen:n, 10 je Seite aus talents_kampagnen)
  naechste: 'alle', kseite: String(n(S.kampagnen)) };
const txt = v => { const t = String(v ?? '').trim(); return t.length <= 200 && !/[\x00-\x1f\x7f]/.test(t) ? t : ''; };
const ordner = { an: String(P.ob || '') === '1', pfad: txt(P.op).replace(/\/+$/, ''), umbenennen: txt(P.ou) };
// Content-Galerie (Stefan 21.10.2026): Format-Filter (?format=reel|karussell|bild|video|story, prüft talents_beitraege) und Wahl der Ansicht (?ca=galerie|tabelle;
// gespeichert je Person als ansicht kacheln|liste im Zustand talent.content, siehe „Daten laden“)
const format = ['reel', 'karussell', 'bild', 'video', 'story'].includes(String(P.format || '')) ? String(P.format) : '';
const ansicht = { galerie: 'kacheln', tabelle: 'liste' }[String(P.ca || '')] || '';
return [{ json: { ordner, werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', id, JSON.stringify(f), String(n(S.content)), String(n(S.notizen)), JSON.stringify(af), format, ansicht] } }];

// Ordner-Auftrag (ALLY 25, Migration 67): Ordner im Speicherort nur auflisten, wenn die Person sie durchsuchen will (ob=1), den Talent-Bereich dieses Talents einstellen
// darf und das Recht am Speicherort hat (talent_ordner_ui) und ein geprüfter Speicherort eingebunden ist. Sonst kein Aufruf von SPEICHER 1 (lesen = false).
const P = $('Parameter').first().json;
const D = $('Daten laden').first().json || {};
const O = D.o && D.o.ok === true && D.o.darf === true ? D.o : null;
const lesen = !!(P.ordner && P.ordner.an && O && O.darf_freigeben === true && O.bereit === true);
return [{ json: { lesen, aktion: 'ordner_liste', token: String(P.werte[0] || ''), daten: { pfad: lesen ? String(P.ordner.pfad || '') : '' } } }];

// Werkzeug-Parameter (ALLY 25, BA10 Teil 3, Migration 71): KI-Werkzeuge eines Talents w = konzept (Content-Strategie), wf (Content-Insights), marken (Brand-Matching),
// mails (Korrespondenz), texte (Textentwürfe); sonst gilt das bisherige Talent-Profil („Werkzeug?“). Nur geprüfte Werte wie ALLY 8 („Anfrage lesen“, t3):
// Talent und Nummern nur als Ziffern, Zeitraum und Kanal nach Muster, Seiten (blatt) 1–9999.
const E = $('Start').first().json;
const P = E.parameter || {};
const w = ['konzept', 'wf', 'marken', 'mails', 'texte'].includes(String(P.w || '')) ? String(P.w) : '';
const z9 = v => /^[0-9]{1,9}$/.test(String(v ?? '')) ? String(v) : '';
const s4 = v => /^[0-9]{1,4}$/.test(String(v ?? '')) && Number(v) >= 1 ? String(Number(v)) : '';
const iso = v => /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(v ?? '')) ? String(v) : '';
const ohneLeer = o => Object.fromEntries(Object.entries(o).filter(x => x[1] !== '' && x[1] !== undefined));
const tid = z9(P.id);
const filter = w === 'wf' ? ohneLeer({ kanal: /^([a-z_]{1,20}|k[0-9]{1,9})$/.test(String(P.kanal || '')) ? String(P.kanal) : '', zeitraum: /^[a-z0-9]{1,12}$/.test(String(P.zeitraum || '')) ? String(P.zeitraum) : '',
    von: iso(P.von), bis: iso(P.bis) })
  : w === 'marken' ? ohneLeer({ talent_id: tid, lauf_id: z9(P.lauf) })
  : w === 'mails' ? ohneLeer({ seite: s4(P.blatt) })
  : w === 'texte' ? ohneLeer({ talent_id: tid, text_id: z9(P.text), seite: s4(P.blatt) }) : {};
return [{ json: { werte: [/^[0-9a-f]{64}$/.test(String(E.sitzung || '')) ? String(E.sitzung) : '', w, tid || '0', JSON.stringify(filter)] } }];

// Werkzeug beschreiben (ALLY 25, BA10 Teil 3, Migration 71, Stefan 20.10.2026): KI-Werkzeuge eines Talents wie ALLY 8 („Talents-Werkzeuge einsetzen“), Inhalte und Aktionen
// unverändert, Darstellung mit dem Baukasten (nur JSON). Begriffe wie Teil B: Strategie › Content-Strategie (kz_*), Performance › Content-Insights (wf_erstellen),
// Strategie › Brand-Matching (ms_*), Kommunikation › Korrespondenz (me_anlegen), Kommunikation › Textentwürfe (tx_*, me_anlegen).
// Die KI läuft nur auf ausdrücklichen Klick (Knopf mit Rückfrage); ALLY 20 startet danach „TALENTS KI-Aufträge“ bzw. „TALENTS Mail-Entwürfe“.
// Ally verschickt nichts: Mails nur als Entwurf im Entwurfsordner. Texte zu Meldungen, Fehlern und Zuständen setzt die Datenbank.
const E = $('Start').first().json;
const D = $input.first().json || {};
const P = E.parameter || {};
const W = String(D.w || '');
const R = D.r && typeof D.r === 'object' ? D.r : null;
const PN = String(D.produkt_name || '').trim(), WER = PN || 'Der Assistent';
const LI = x => Array.isArray(x) ? x : [];
const id9 = v => /^[0-9]{1,9}$/.test(String(v ?? '')) ? String(v) : '';
const id15 = v => /^[0-9]{1,15}$/.test(String(v ?? '')) ? String(v) : '';
const ganz = v => { const x = Number(v); return isFinite(x) ? Math.round(x) : 0; };
const ISO = v => /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(v || '')) ? String(v) : '';
const tid = id9(D.talent) || id9(P.id);
const TITEL = { konzept: 'Content-Strategie', wf: 'Content-Insights', marken: 'Brand-Matching', mails: 'Korrespondenz', texte: 'Textentwürfe' };
const BESCHR = { konzept: 'Positionierung, Ziele mit Soll/Ist, Format-Mix und Themenplan.', wf: 'Was beim Talent überdurchschnittlich funktioniert, aus den gespeicherten Zahlen.',
  marken: 'Passende Marken für Kooperationen nach den Kriterien der Agentur.', mails: 'Mails mit dem Talent in deinen Postfächern und Mail-Entwürfe.',
  texte: 'Entwürfe der KI für Mediakit, Kampagnenbericht und Antworten an Marken.' };
const KI_INFO = 'Vorschlag der KI auf Basis der gespeicherten Zahlen. Bitte prüfen.';
const titel = TITEL[W] || 'Talent';
const tName = String((R && (R.talent_name || (R.talent && (R.talent.name || R.talent.anzeigename)))) || 'Talent');
const profil = { seite: 'talent', parameter: { id: tid } };
const hier = (extra, anker) => ({ seite: 'talent', parameter: Object.assign({ id: tid, w: W }, extra || {}), anker });
const kopf = () => ({ schluessel: 'talent', art: 'funktion', titel: titel + ' – ' + tName, beschreibung: BESCHR[W] || '',
  krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: 'Dashboard', ziel: { seite: 'talents' } }, { text: tName, ziel: profil }, { text: titel }],
  aktionen: Object.keys(TITEL).filter(k => k !== W).map(k => ({ text: TITEL[k], ziel: { seite: 'talent', parameter: { id: tid, w: k } } })).concat([{ text: 'Zum Talent-Profil', ziel: profil }]) });
