if (W === 'marken') {
  const AG = R.darf_agentur === true, FE = R.felder || {}, EIN = LI(FE.einschliessen), AUS = LI(FE.ausschliessen);
  const LA = R.lauf && typeof R.lauf === 'object' ? R.lauf : null;
  const kTab = (id, KL, agentur) => ({ typ: 'tabelle', id, titel: agentur ? 'Für die ganze Agentur' : 'Für dieses Talent', spalten: [{ schluessel: 'k', titel: 'Kriterium' }, { schluessel: 'g', titel: 'Grund' }, { schluessel: 'a', titel: 'Aktion' }],
    zeilen: LI(KL).map(k => ({ zellen: { k: { text: String(k.richtung_name || '') + ': ' + String(k.feld_name || ''), fett: true, neben: String(k.wert_name || k.wert || '') }, g: [k.grund, k.datum].filter(Boolean).join(' · ') || '–',
      a: (!agentur || AG) && id9(k.kriterium_id) ? { aktion: { text: k.feld === 'marke' ? 'Von der Sperrliste nehmen' : 'Entfernen', aktion: 'ms_kriterium_entfernen', werte: { kriterium_id: id9(k.kriterium_id) } } } : '' } })),
    sortierung: {}, seite: 1, je_seite: Math.max(1, LI(KL).length), gesamt: LI(KL).length, leer: 'Keine.' });
  const optListe = EIN.filter(x => LI(x.optionen).length);
  const kForm = { typ: 'formular', id: 'kriterium', aktion: 'ms_kriterium_hinzufuegen', werte: { talent_id: tid }, spalten: 2, titel: 'Kriterium hinzufügen', felder: [
    { typ: 'auswahl', name: 'ebene', label: 'Gilt für', wert: 'talent', optionen: [opt('talent', 'dieses Talent')].concat(AG ? [opt('agentur', 'die ganze Agentur')] : []) },
    { typ: 'auswahl', name: 'kriterium', label: 'Kriterium', pflicht: true, wert: '', optionen: EIN.map(x => opt('einschliessen|' + x.feld, 'Einschließen: ' + x.name)).concat(AUS.map(x => opt('ausschliessen|' + x.feld, 'Ausschließen: ' + x.name))) }]
    .concat(optListe.length ? [{ typ: 'auswahl', name: 'wert_wahl', label: 'Wert aus der Liste', wert: '', optionen: [opt('', '–')].concat([].concat(...optListe.map(x => LI(x.optionen).map(o => opt(x.feld + '|' + o.wert, x.name + ': ' + o.name))))),
      info: 'Nur bei ' + optListe.map(x => x.name).join(', ') + '.' }] : [])
    .concat([{ typ: 'text', name: 'wert', label: 'Wert', autocomplete: 'off', info: 'Bei den übrigen Kriterien als Text, z. B. eine Branche oder ein Markenname.' }, { typ: 'text', name: 'grund', label: 'Grund (optional)' }]),
    knoepfe: [{ text: 'Kriterium hinzufügen', art: 'neben' }] };
  abschnitte.push({ id: 'kriterien', titel: 'Kriterien', zahl: String(LI(R.kriterien_talent).length + LI(R.kriterien_agentur).length), offen_standard: false, info: 'Welche Marken passen und welche ausgeschlossen sind.',
    inhalt: [kTab('krit-talent', R.kriterien_talent, false), kTab('krit-agentur', R.kriterien_agentur, true), kForm] });
  const WK = R.wirksam && typeof R.wirksam === 'object' ? R.wirksam : {};
  const fname = (liste, f) => (liste.find(x => x.feld === f) || {}).name || f;
  const wname = (f, w) => (((EIN.find(x => x.feld === f) || {}).optionen || []).find(o => o.wert === w) || {}).name || w;
  const gilt = [].concat(Object.entries(WK.einschliessen || {}).map(([f, w]) => fname(EIN, f) + ': ' + LI(w).map(x => wname(f, x)).join(', ')),
    Object.entries(WK.ausschliessen || {}).map(([f, w]) => 'nicht ' + fname(AUS, f) + ': ' + LI(w).join(', ')), WK.nogos ? ['No-Gos des Talents: ' + WK.nogos] : []);
  if (R.darf_starten === true) {
    const su = [];
    if (gilt.length) su.push({ typ: 'text', ton: 'grau', text: 'Es gelten außerdem: ' + gilt.join(' · ') });
    if (R.ki_hinweis) su.push({ typ: 'text', ton: 'grau', text: String(R.ki_hinweis) });
    else su.push({ typ: 'formular', id: 'suche', aktion: 'ms_suche_starten', werte: { talent_id: tid }, spalten: 2, zurueck_ziel: hier({}, 'a-ergebnis'),
      frage: 'Die KI sucht jetzt passende Marken mit Websuche (zählt zum KI-Budget). Starten?',
      info: ['Kriterien nur für diese Suche (optional). Mehrere Werte mit Komma trennen (höchstens 10 je Feld).', 'Jede Suche nutzt die Websuche der KI (Kosten unter Einstellungen › Funktionen › Talents › KI-Funktionen).'],
      felder: EIN.map(x => LI(x.optionen).length ? { typ: 'auswahl', name: 'ein__' + x.feld, label: String(x.name), wert: '', optionen: [opt('', 'egal')].concat(LI(x.optionen).map(o => opt(o.wert, o.name))) }
        : { typ: 'text', name: 'ein__' + x.feld, label: String(x.name), autocomplete: 'off' }).concat(AUS.map(x => ({ typ: 'text', name: 'aus__' + x.feld, label: 'Nicht: ' + x.name, autocomplete: 'off' }))),
      knoepfe: [{ text: 'Marken suchen' }] });
    abschnitte.push({ id: 'suche', titel: 'Marken suchen', offen_standard: !LA, inhalt: su });
    seite.hauptaktion = { text: 'Marken suchen', ziel: hier({}, 'a-suche') };
  }
  const e = [];
  const LF = LI(R.laeufe).filter(x => id9(x.lauf_id));
  if (LF.length > 1) e.push({ typ: 'unterueberschrift', text: 'Frühere Suchen' }, { typ: 'liste', eintraege: LF.map(x => ({ text: [x.datum, x.status_text].filter(Boolean).join(' · '),
    marke: LA && id9(LA.lauf_id) === id9(x.lauf_id) ? { text: 'gezeigt' } : undefined, ziel: hier({ lauf: id9(x.lauf_id) }, 'a-ergebnis'), ziel_text: 'Zeigen' })) });
  if (!LA) e.push({ typ: 'text', ton: 'grau', text: 'Noch keine Suche.' });
  else {
    e.push({ typ: 'text', ton: LA.status === 'fehler' ? 'warn' : 'grau', text: String(LA.status_text || '') });
    if (R.hinweis_quellen) e.push({ typ: 'text', ton: 'grau', text: String(R.hinweis_quellen) });
    const lauf = id9(LA.lauf_id);
    const treffer = (t, mitForm) => {
      const tr = id9(t.treffer_id);
      e.push({ typ: 'unterueberschrift', text: String(t.marke || t.website || 'Marke') + (t.gesperrt === true ? ' (gesperrt)' : '') });
      e.push({ typ: 'paare', eintraege: [['Website', t.website], ['Branche', t.branche], ['Begründung', t.begruendung], ['Quelle', [t.quelle_titel, t.quelle_url].filter(Boolean).join(' – ')],
        ['Kontaktweg', [t.kontaktweg_name, t.kontakt].filter(Boolean).join(': ')]].filter(x => x[1]).map(x => ({ label: x[0], wert: String(x[1]) })) });
      if (!mitForm || !tr) return;
      if (t.bewertung) e.push({ typ: 'text', ton: 'grau', text: String(t.bewertung_text || '') + (t.bewertung_grund ? ': ' + t.bewertung_grund : '') },
        { typ: 'aktion', text: 'Bewertung zurücknehmen', aktion: 'ms_bewertung_zuruecknehmen', werte: { treffer_id: tr } });
      else e.push({ typ: 'formular', id: 'bewerten-' + tr, aktion: 'ms_bewerten', werte: { treffer_id: tr }, spalten: 2, zurueck_ziel: hier(lauf ? { lauf } : {}, 'a-ergebnis'), felder: [
        { typ: 'text', name: 'grund', label: 'Grund (optional)' },
        { typ: 'auswahl', name: 'sperren', label: 'Bei „passt nicht“', wert: '', optionen: [opt('', 'nicht sperren'), opt('talent', 'für dieses Talent sperren')].concat(AG ? [opt('agentur', 'für die Agentur sperren')] : []) }],
        knoepfe_in_reihe: false, knoepfe: [{ text: 'passt', name: 'bewertung', wert: 'passt', art: 'neben' }, { text: 'passt nicht', name: 'bewertung', wert: 'passt_nicht', art: 'neben' }] });
    };
    const TR = LI(LA.treffer).slice(0, 12), BK = LI(LA.bekannt).slice(0, 12);
    for (const t of TR) treffer(t, true);
    if (!TR.length && LA.laeuft !== true) e.push({ typ: 'text', ton: 'grau', text: 'Keine neuen Marken gefunden.' });
    if (BK.length) { e.push({ typ: 'unterueberschrift', text: 'Bereits bekannt (' + BK.length + ')' }); for (const t of BK) treffer(t, false); }
  }
  abschnitte.push({ id: 'ergebnis', titel: 'Ergebnis', offen_standard: true, info: ['Gefundene Marken mit Bewertung (passt, passt nicht).', LA && LI(LA.treffer).length ? KI_INFO : ''].filter(Boolean), inhalt: e });
}

// ========== Kommunikation › Korrespondenz ==========
if (W === 'mails') {
  const PF = LI(R.postfaecher).filter(p => p && p.adresse);
  const ML = LI(R.mails);
  const m = [];
  if (R.email_hinterlegt === false) m.push({ typ: 'text', ton: 'grau', text: 'Für dieses Talent ist keine E-Mail hinterlegt. Mails werden über die hinterlegte E-Mail erkannt.' });
  m.push({ typ: 'tabelle', id: 'mails', titel: 'Mails', spalten: [{ schluessel: 'betreff', titel: 'Betreff' }, { schluessel: 'datum', titel: 'Datum' }, { schluessel: 'von', titel: 'Von' }, { schluessel: 'postfach', titel: 'Postfach' }],
    zeilen: ML.map(x => ({ zellen: { betreff: { text: String(x.betreff || '(ohne Betreff)'), fett: true }, datum: String(x.datum || ''), von: String(x.absender || ''), postfach: String(x.postfach || '') } })),
    sortierung: {}, seite: 1, je_seite: Math.max(1, ML.length), gesamt: ML.length, leer: 'Keine Mails in deinen Postfächern.' });
  for (const b of blaettern({}, 'a-mails')) m.push(b);
  abschnitte.push({ id: 'mails', titel: 'Mails', zahl: String(ML.length), offen_standard: true, info: 'Mails mit ' + tName + ' in deinen Postfächern: Datum, Absender und Betreff. Den Mailtext zeigt das Mailprogramm.', inhalt: m });
  const KP = LI(R.kampagnen).filter(k => id9(k.kampagne_id));
  const DT = LI((R.dateien || {}).dateien).filter(d => id15(d.datei_id));
  const e = [];
  if (!PF.length) e.push({ typ: 'text', ton: 'grau', text: 'Kein Postfach mit eingeschalteten Mail-Entwürfen.' });
  else {
    const ARTEN = (R.einladung_offen === true ? [opt('einladung', 'Einladung')] : []).concat([opt('erinnerung', 'Erinnerung Kampagne'), opt('bericht_talent', 'Bericht an das Talent'), opt('bericht_marke', 'Bericht an die Marke')]);
    const felder = [{ typ: 'auswahl', name: 'art', label: 'Art', pflicht: true, wert: R.einladung_offen === true ? 'einladung' : 'erinnerung', optionen: ARTEN,
      info: R.einladung_offen === true ? undefined : 'Einladung: Zuerst einen Einladungslink erzeugen.' }];
    if (KP.length) felder.push({ typ: 'auswahl', name: 'kampagne_id', label: 'Kampagne', wert: '', optionen: [opt('', '–')].concat(KP.map(k => opt(id9(k.kampagne_id), [k.titel || k.name, k.zeitraum_text].filter(Boolean).join(' · ')))),
      info: 'Für „Erinnerung Kampagne“ und „Bericht an die Marke“.' });
    if (DT.length) felder.push({ typ: 'mehrfach', name: 'dateien', label: 'Anhänge (höchstens 5)', breite: 'voll', wert: [], info: 'Für die Berichte an das Talent und an die Marke.',
      optionen: DT.slice(0, 10).map(d => ({ wert: id15(d.datei_id), text: String(d.name || ''), neben: [d.art_name, d.datum, d.groesse_text].filter(Boolean).join(' · ') })) });
    felder.push({ typ: 'email', name: 'an', label: 'An (E-Mail der Marke)', autocomplete: 'off', info: 'Nur für „Bericht an die Marke“. Sonst geht der Entwurf an die E-Mail des Talents.' },
      { typ: 'text', name: 'an_name', label: 'Name der Marke' }, postfachFeld(PF));
    e.push({ typ: 'formular', id: 'entwurf-neu', aktion: 'me_anlegen', werte: { talent_id: tid }, spalten: 2, felder, zurueck_ziel: hier({}, 'a-entwuerfe'), knoepfe: [{ text: 'Entwurf ablegen' }] });
    seite.hauptaktion = { text: 'Mail-Entwurf anlegen', ziel: hier({}, 'a-entwurf-neu') };
  }
  abschnitte.push({ id: 'entwurf-neu', titel: 'Mail-Entwurf anlegen', offen_standard: false, info: ['Einladung, Erinnerung zur Kampagne oder Bericht. Nur als Entwurf im Entwurfsordner.', String(R.hinweis || '')].filter(Boolean), inhalt: e });
  const EW = LI(R.entwuerfe);
  abschnitte.push({ id: 'entwuerfe', titel: 'Entwürfe', zahl: String(EW.length), offen_standard: false, info: 'Abgelegte Mail-Entwürfe zu diesem Talent.', inhalt: [{ typ: 'tabelle', id: 'entwuerfe', titel: 'Entwürfe',
    spalten: [{ schluessel: 'betreff', titel: 'Betreff' }, { schluessel: 'art', titel: 'Art und Datum' }, { schluessel: 'an', titel: 'An' }, { schluessel: 'stand', titel: 'Stand' }],
    zeilen: EW.map(x => ({ zellen: { betreff: { text: String(x.betreff || ''), fett: true }, art: [x.art_name, x.datum].filter(Boolean).join(' · ') || '–', an: [x.an ? 'an ' + x.an : '', x.postfach].filter(Boolean).join(' · ') || '–',
      stand: String(x.status_text || '–') } })), sortierung: {}, seite: 1, je_seite: Math.max(1, EW.length), gesamt: EW.length, leer: 'Noch keine Entwürfe.' }] });
  abschnitte.push({ id: 'dateien', titel: 'Dateien', zahl: String(DT.length), offen_standard: false, info: 'Reports, Strategien und Mediakits des Talents, auch als Anhang.',
    inhalt: [{ typ: 'tabelle', id: 'dateien', titel: 'Dateien', spalten: [{ schluessel: 'name', titel: 'Datei' }, { schluessel: 'art', titel: 'Art und Ort' }],
      zeilen: DT.map(d => ({ zellen: { name: { text: String(d.name || ''), fett: true }, art: [d.art_name, d.ort, d.groesse_text, d.datum].filter(Boolean).join(' · ') || '–' } })),
      sortierung: {}, seite: 1, je_seite: Math.max(1, DT.length), gesamt: DT.length, leer: 'Noch keine Dateien.' }] });
}

// ========== Kommunikation › Textentwürfe (zu diesem Talent) ==========
if (W === 'texte') {
  const X = R.text && typeof R.text === 'object' ? R.text : null, xid = X ? id9(X.text_id) : '';
  seite.hauptaktion = { text: 'Text erstellen', fenster: 'neu' };
  const TL = LI(R.texte).filter(x => id9(x.text_id));
  abschnitte.push({ id: 'texte', titel: 'Texte', zahl: String(TL.length), offen_standard: true, info: 'Mediakit-Text, Kampagnen-Zusammenfassung, Antwort an eine Marke.',
    inhalt: [{ typ: 'tabelle', id: 'texte', titel: 'Texte', spalten: [{ schluessel: 'titel', titel: 'Titel' }, { schluessel: 'art', titel: 'Art' }, { schluessel: 'stand', titel: 'Stand' }],
      zeilen: TL.map(x => ({ aktiv: id9(x.text_id) === xid, zellen: { titel: { text: String(x.titel || 'Text'), ziel: hier({ text: id9(x.text_id), blatt: ganz(R.seite) > 1 ? String(ganz(R.seite)) : '' }) },
        art: String(x.art_name || '–'), stand: [x.status_text, x.datum].filter(Boolean).join(' · ') || '–' } })),
      sortierung: {}, seite: 1, je_seite: Math.max(1, TL.length), gesamt: TL.length, leer: 'Noch keine Texte.' }].concat(blaettern({}, 'a-texte')) });
  const AR = LI(R.arten), KP = LI(R.kampagnen).filter(k => id9(k.kampagne_id));
  const bra = AR.reduce((o, x) => (o[x.braucht] = (o[x.braucht] || []).concat(x.name), o), {});
  const felder = [{ typ: 'auswahl', name: 'art', label: 'Art', pflicht: true, wert: '', optionen: AR.map(x => opt(x.wert, x.name)) }, { typ: 'versteckt', name: 'talent_id', wert: tid }];
  if (KP.length) felder.push({ typ: 'auswahl', name: 'kampagne_id', label: 'Kampagne', wert: '', optionen: [opt('', '–')].concat(KP.map(k => opt(id9(k.kampagne_id), [k.titel || k.name, k.zeitraum_text].filter(Boolean).join(' · ')))),
    info: 'Für ' + (bra.kampagne || ['die Zusammenfassung']).join(', ') + '.' });
  else if (bra.kampagne) felder.push({ typ: 'anzeige', name: 'kampagne_info', label: 'Kampagne', wert: 'Dieses Talent ist in keiner Kampagne.' });
  felder.push({ typ: 'textbereich', name: 'eingabe', label: 'Anfrage der Marke einfügen', breite: 'voll', zeilen: 6, info: 'Für ' + (bra.anfrage || ['die Antwort an eine Marke']).join(', ') + '.' });
  const neu = [];
  if (R.ki_hinweis) neu.push({ typ: 'text', ton: 'grau', text: String(R.ki_hinweis) });
  else neu.push({ typ: 'formular', id: 'text-neu', aktion: 'tx_erstellen', spalten: 2, felder, zurueck_ziel: hier({}, 'a-texte'),
    info: 'Die KI erstellt einen Entwurf aus den gespeicherten Daten. Sie arbeitet nur auf Anforderung; die Nutzung zählt zum KI-Budget.', knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Text erstellen lassen' }] });
  fenster.push({ id: 'neu', art: 'dialog', titel: 'Neuer Text für ' + tName, inhalt: neu });
  if (X) {
    const xi = [{ typ: 'paare', eintraege: [{ label: 'Art', wert: String(X.art_name || '–') }, { label: 'Stand', wert: String(X.status_text || '–') }] }];
    if (X.eingabe) xi.push({ typ: 'unterueberschrift', text: 'Anfrage der Marke' }, { typ: 'text', text: String(X.eingabe) });
    if (X.laeuft === true) xi.push({ typ: 'text', ton: 'grau', text: 'Der Text wird gerade erstellt. Bitte die Seite in etwa einer Minute neu laden.' });
    else if (X.status === 'fehler') xi.push({ typ: 'aktion', text: 'Löschen', aktion: 'tx_loeschen', werte: { text_id: xid }, frage: 'Diesen Text löschen?' });
    else {
      const hw = LI(X.hinweise).map(v => typeof v === 'string' ? v : (v && (v.text || v.zahl)) || '').filter(Boolean);
      if (hw.length) xi.push({ typ: 'text', ton: 'warn', text: 'Bitte prüfen: ' + hw.join(', ') });
      xi.push({ typ: 'formular', id: 'text-speichern', aktion: 'tx_speichern', werte: { text_id: xid }, info: KI_INFO, felder: [
        { typ: 'text', name: 'titel', label: 'Titel', wert: String(X.titel || ''), breite: 'voll' }, { typ: 'textbereich', name: 'text', label: 'Text', wert: String(X.text || ''), zeilen: 12, breite: 'voll' }],
        knoepfe: [{ text: 'Speichern' }] });
      xi.push({ typ: 'aktion', text: 'Löschen', aktion: 'tx_loeschen', werte: { text_id: xid }, frage: 'Diesen Text löschen?' });
      const PF = LI(R.postfaecher).filter(p => p && p.adresse);
      if (X.als_mail_moeglich === true) {
        xi.push({ typ: 'unterueberschrift', text: 'Als Mail-Entwurf ablegen', info: WER + ' legt die Mail nur als Entwurf im Entwurfsordner ab. Verschickt wird sie nur von dir.' });
        if (PF.length) xi.push({ typ: 'formular', id: 'text-mail', aktion: 'me_anlegen', werte: { art: 'antwort_marke', text_id: xid, talent_id: id9(X.talent_id) || tid }, spalten: 2, felder: [
          { typ: 'email', name: 'an', label: 'An (E-Mail der Marke)', pflicht: true, autocomplete: 'off' }, { typ: 'text', name: 'an_name', label: 'Name der Marke' }, postfachFeld(PF)],
          knoepfe: [{ text: 'Entwurf ablegen', art: 'neben' }] });
        else xi.push({ typ: 'text', ton: 'grau', text: 'Kein Postfach mit eingeschalteten Mail-Entwürfen.' });
      }
    }
    fenster.push({ id: 'text', art: 'seitenfenster', offen: true, titel: String(X.titel || 'Text'), untertitel: String(X.art_name || ''), schliessen_ziel: hier({}, 'a-texte'), inhalt: xi });
  }
}
return [{ json: { inhalt: { seite, abschnitte, fenster } } }];

parameters.query:
-- Reports laden (ALLY 25, BA10 Teil 4, Stefan 21.10.2026): erzeugte Reports dieses Talents wie ALLY 8 (talents_berichte_liste mit Filter Talent, die zehn neuesten;
-- Sichtbarkeit und Zuständigkeit prüft die Datenbank). Nur lesend. $1 Sitzung, $2 Talent.
SELECT CASE WHEN (c->>'ok')::boolean AND $2::text ~ '^[0-9]{1,9}$' THEN talents_berichte_liste(c->>'u', c->>'zugriff' = 'alle', jsonb_build_object('talent', $2::text)) END AS b
FROM talents_ansicht_start($1::text) c;

