// Werkzeug-Downloads (ALLY 25, BA10 Teil 4, Stefan 21.10.2026): ergänzt „Werkzeug beschreiben“ (Korrespondenz › Dateien), ohne es zu ändern: je Datei „Herunterladen“
// wie ALLY 8 – über Ally (Seite datei, ta = Datei der Talents-Ablage; ALLY 20 prüft Rechte und holt die Datei über TALENTS Ablage), nie ein Direktlink.
const E = $('Start').first().json;
const WD = $('Werkzeug-Daten').first().json || {};
const R = WD.r && typeof WD.r === 'object' ? WD.r : {};
const id9 = v => /^[0-9]{1,9}$/.test(String(v ?? '')) ? String(v) : '';
const tid = id9(WD.talent) || id9((E.parameter || {}).id);
const DT = (Array.isArray((R.dateien || {}).dateien) ? R.dateien.dateien : []).filter(d => /^[0-9]{1,15}$/.test(String((d || {}).datei_id ?? '')));
return $input.all().map(it => {
  const j = it.json;
  const AB = j && j.inhalt && Array.isArray(j.inhalt.abschnitte) ? j.inhalt.abschnitte : [];
  const a = String(WD.w || '') === 'mails' ? AB.find(x => x && x.id === 'dateien') : null;
  const tab = a && Array.isArray(a.inhalt) ? a.inhalt.find(b => b && b.typ === 'tabelle' && b.id === 'dateien') : null;
  if (!tab || !Array.isArray(tab.zeilen) || tab.zeilen.length !== DT.length || !Array.isArray(tab.spalten)) return { json: j };
  a.info = 'Reports, Strategien und Mediakits des Talents zum Herunterladen, auch als Anhang.';
  tab.spalten.push({ schluessel: 'laden', titel: '' });
  tab.zeilen.forEach((z, k) => { if (z && z.zellen) z.zellen.laden = { text: 'Herunterladen', ziel: { seite: 'datei', parameter: Object.assign({ ta: String(DT[k].datei_id) }, tid ? { t: tid } : {}) } }; });
  return { json: j };
});

parameters.query:
-- Datenimport-Daten (ALLY 25, BA10 Teil 4, Stefan 21.10.2026): Zahlen ohne Verbindung (Screenshot, PDF, Export, Mail, Chat) eines Talents wie ALLY 8
-- („Seite laden“, b=zahlen): talents_manuell_web prüft Sitzung, Talents-Recht und Zuständigkeit selbst. Nur lesend. $1 Sitzung, $2 Talent, $3 Filter (Seite der Werte).
SELECT $2::text AS talent, talents_manuell_web($1::text, $2::integer, $3::jsonb) AS r, produkt_name() AS produkt_name;

parameters.jsCode:
// Datenimport beschreiben (ALLY 25, BA10 Teil 4, Stefan 21.10.2026): Daten › Datenimport (bisher „Zahlen ohne Verbindung“) wie ALLY 8 („Talents-Werkzeuge einsetzen“, zahlen):
// Datei hochladen (Screenshot, PDF, Export), Vorschläge prüfen und bestätigen bzw. verwerfen, bestätigte Werte (löschen), von Hand eintragen. Formulare gehen an ALLY 20
// (tm_hochladen über app/datei, tm_bestaetigen, tm_verwerfen, tm_wert_neu, tm_wert_loeschen) und von dort an talents_manuell_web_aktion wie TALENTS Web.
// Ausgelesen wird nur nach dem Hochladen (zählt zum KI-Budget, Rückfrage). Doppelte Daten (Migration 65) prüft die Datenbank beim Speichern; Entscheidung im Talent-Profil.
const E = $('Start').first().json;
const D = $input.first().json || {};
const P = E.parameter || {};
const R = D.r && typeof D.r === 'object' ? D.r : null;
const LI = x => Array.isArray(x) ? x : [];
const id9 = v => /^[0-9]{1,9}$/.test(String(v ?? '')) ? String(v) : '';
const id15 = v => /^[0-9]{1,15}$/.test(String(v ?? '')) ? String(v) : '';
const ISO = v => /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(v || '')) ? String(v) : '';
const ganz = v => { const x = Number(v); return isFinite(x) ? Math.round(x) : 0; };
const PN = String(D.produkt_name || '').trim(), WER = PN || 'Der Assistent';
const tid = id9(D.talent) || id9(P.id);
const tName = String((R && R.talent && R.talent.anzeigename) || 'Talent');
const profil = { seite: 'talent', parameter: { id: tid } };
const hier = (extra, anker) => ({ seite: 'talent', parameter: Object.assign({ id: tid, w: 'zahlen' }, extra || {}), anker });
const titel = 'Datenimport';
const kopf = { schluessel: 'talent', art: 'funktion', titel: titel + ' – ' + tName, beschreibung: 'Manuelle Daten: Bild, PDF oder Export der Insights hochladen, prüfen und bestätigen.',
  krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: 'Dashboard', ziel: { seite: 'talents' } }, { text: tName, ziel: profil }, { text: titel }],
  aktionen: [{ text: 'Zum Talent-Profil', ziel: profil }] };
if (!R || R.ok !== true || !tid) {
  return [{ json: { inhalt: { seite: Object.assign({}, kopf, { titel, aktionen: [] }), abschnitte: [{ id: 'fehler', titel, offen_standard: true, inhalt: [
    { typ: 'text', ton: 'warn', text: String((R && R.fehler) || 'Die Daten konnten nicht geladen werden. Bitte die Seite neu laden.') },
    { typ: 'aktion', text: tid ? 'Zum Talent' : 'Zu den Talents', ziel: tid ? profil : { seite: 'talents' } }] }] } } }];
}
const abschnitte = [];
const opt = (w, t) => ({ wert: String(w ?? ''), text: String(t ?? '') });
// ---------- Datei hochladen ----------
const HL = R.hochladen && typeof R.hochladen === 'object' ? R.hochladen : null;
if (HL) {
  kopf.hauptaktion = { text: 'Datei hochladen', ziel: hier({}, 'a-hochladen') };
  abschnitte.push({ id: 'hochladen', titel: 'Datei hochladen', offen_standard: true, info: 'Bild, PDF oder Export der Insights. Gespeichert wird erst nach deiner Bestätigung.',
    inhalt: [R.erklaerung ? { typ: 'text', ton: 'grau', text: String(R.erklaerung) } : null,
      { typ: 'formular', id: 'hochladen', aktion: 'tm_hochladen', datei: true, werte: { talent_id: tid },
        frage: 'Datei hochladen und von ' + WER + ' auslesen lassen? Das zählt zum KI-Budget. Gespeichert wird erst nach deiner Bestätigung.',
        felder: [{ typ: 'datei', name: 'datei', label: 'Datei', accept: String(HL.accept || ''), pflicht: true, info: String(HL.text || '') }],
        knoepfe: [{ text: 'Hochladen und auslesen' }] }].filter(Boolean) });
}
// ---------- Zur Prüfung ----------
const VS = LI(R.vorschlaege).filter(v => id15(v.id));
const pr = [];
for (const v of VS) {
  const vid = id15(v.id);
  pr.push({ typ: 'unterueberschrift', text: [v.quelle_text, v.eingang_text].filter(Boolean).join(' · ') || 'Vorschlag', info: String(v.status_text || '') || undefined });
  for (const z of LI(v.hinweise)) { const t = typeof z === 'string' ? z : (z && (z.text || z.hinweis)) || ''; if (t) pr.push({ typ: 'text', ton: 'grau', text: String(t) }); }
  if (v.fehler) pr.push({ typ: 'hinweis', ton: 'warn', text: String(v.fehler) });
  if (v.status === 'auslesen') pr.push({ typ: 'text', ton: 'grau', text: 'Wird ausgelesen … Bitte die Seite in einer Minute neu laden.' });
  else if (v.status === 'offen') {
    const felder = [];
    for (const w of LI(v.werte).filter(w => /^[0-9]{1,3}$/.test(String(w.nr ?? '')))) {
      const n = String(w.nr), fehlt = LI(w.fehlt), zrFehlt = fehlt.includes('zeitraum');
      const neben = [[w.plattform_name, w.konto].filter(Boolean).join(' '), w.bereich === 'beitrag' && w.beitrag_datum ? 'Beitrag vom ' + w.beitrag_datum : ''].filter(Boolean).join(' · ');
      felder.push({ typ: 'haken', name: 'n' + n + '_ja', label: String(w.kennzahl_name || ''), neben, wert_an: 'ja', an: !fehlt.length, breite: 'voll',
        info: fehlt.length ? (zrFehlt ? 'Bitte den Zeitraum ergänzen.' : 'Bitte prüfen und ergänzen.') : undefined });
      if (w.bereich === 'zielgruppe') felder.push({ typ: 'anzeige', name: 'n' + n + '_text', label: 'Werte', wert: String(w.werte_text || ''), breite: 'voll' });
      else felder.push({ typ: 'text', name: 'n' + n + '_wert', label: 'Wert', wert: String(w.wert_text || '') });
      if (w.stand) felder.push({ typ: 'datum', name: 'n' + n + '_bis', label: 'Stand', wert: ISO(w.bis), fehler: zrFehlt && !ISO(w.bis) ? 'Bitte das Datum ergänzen.' : undefined });
      else felder.push({ typ: 'datum', name: 'n' + n + '_von', label: 'Von', wert: ISO(w.von), fehler: zrFehlt && !ISO(w.von) ? 'Bitte ergänzen.' : undefined },
        { typ: 'datum', name: 'n' + n + '_bis', label: 'Bis', wert: ISO(w.bis), fehler: zrFehlt && !ISO(w.bis) ? 'Bitte ergänzen.' : undefined });
    }
    pr.push({ typ: 'formular', id: 'vorschlag-' + vid, aktion: 'tm_bestaetigen', werte: { vorschlag_id: vid }, spalten: 3, felder, knoepfe: [{ text: 'Ausgewählte speichern' }] },
      { typ: 'aktion', text: 'Verwerfen', aktion: 'tm_verwerfen', werte: { vorschlag_id: vid }, frage: 'Vorschlag verwerfen? Es wird nichts gespeichert.' });
  } else if (v.status === 'fehler') pr.push({ typ: 'text', ton: 'grau', text: 'Die Zahlen lassen sich unten unter „Von Hand eintragen“ erfassen.' });
}
if (pr.length) abschnitte.push({ id: 'pruefung', titel: 'Zur Prüfung', zahl: String(VS.length), offen_standard: true, info: 'Ausgelesene Werte prüfen, ergänzen und speichern.', inhalt: pr });
// ---------- Bestätigte Werte ----------
const WE = R.werte && typeof R.werte === 'object' ? R.werte : {};
const WZ = LI(WE.zeilen);
abschnitte.push({ id: 'werte', titel: 'Bestätigte Werte', zahl: String(ganz(WE.anzahl)), offen_standard: !pr.length, info: 'Gelten als Zahlen des Talents, gekennzeichnet als „manuell“. Überschneiden sie sich mit automatisch geladenen Zahlen, entscheidest du im Talent-Profil unter „Doppelte Daten prüfen“.',
  inhalt: [{ typ: 'tabelle', id: 'werte', titel: 'Bestätigte Werte', spalten: [{ schluessel: 'kennzahl', titel: 'Kennzahl' }, { schluessel: 'konto', titel: 'Account und Bereich' },
    { schluessel: 'zeitraum', titel: 'Zeitraum' }, { schluessel: 'quelle', titel: 'Quelle' }, { schluessel: 'aktion', titel: 'Aktion' }],
    zeilen: WZ.map(x => ({ zellen: { kennzahl: { text: String(x.kennzahl_name || '') + ': ' + String(x.text || '–'), fett: true },
      konto: [x.plattform_name, x.konto].filter(Boolean).join(' ') + (x.bereich_name ? ' · ' + x.bereich_name : '') || '–', zeitraum: String(x.zeitraum_text || '–'),
      quelle: [x.quelle_text, x.bestaetigt_text].filter(Boolean).join(' · ') || '–',
      aktion: x.darf_loeschen === true && id15(x.id) ? { aktion: { text: 'Löschen', aktion: 'tm_wert_loeschen', werte: { wert_id: id15(x.id) }, frage: 'Diesen Wert löschen?' } } : '' } })),
    sortierung: {}, seite: 1, je_seite: Math.max(1, WZ.length), gesamt: WZ.length, leer: String(WE.leer_text || 'Noch keine bestätigten Werte.') }]
    .concat((s => { const n = Math.max(1, ganz(WE.seiten) || 1), a = [];
      if (s > 1) a.push({ typ: 'aktion', text: 'Vorherige Seite', ziel: hier({ blatt: String(s - 1) }, 'a-werte') });
      if (s < n) a.push({ typ: 'aktion', text: 'Nächste Seite (' + (s + 1) + ' von ' + n + ')', ziel: hier({ blatt: String(s + 1) }, 'a-werte') });
      return a; })(Math.max(1, ganz(WE.seite) || 1))) });
// ---------- Von Hand eintragen ----------
const VH = R.von_hand && typeof R.von_hand === 'object' ? R.von_hand : {};
abschnitte.push({ id: 'von-hand', titel: 'Von Hand eintragen', offen_standard: VS.some(v => v.status === 'fehler'), info: 'Ohne Datei, z. B. aus einem Telefonat oder einer Mail. Bei Follower nur „Bis“ = Stand.',
  inhalt: [{ typ: 'formular', id: 'von-hand', aktion: 'tm_wert_neu', werte: { talent_id: tid }, spalten: 2, felder: [
    { typ: 'auswahl', name: 'plattform', label: 'Plattform', wert: String(VH.plattform_vorschlag || ''), optionen: LI(VH.plattformen).map(x => opt(x.schluessel, x.name)) },
    { typ: 'text', name: 'konto', label: 'Account (optional)', platzhalter: '@name', autocomplete: 'off' },
    { typ: 'auswahl', name: 'kennzahl', label: 'Kennzahl', wert: '', optionen: LI(VH.kennzahlen).map(x => opt(x.schluessel, String(x.name || '') + (x.stand === true ? ' (Stand)' : ''))) },
    { typ: 'text', name: 'wert', label: 'Wert', pflicht: true },
    { typ: 'datum', name: 'von', label: 'Von' }, { typ: 'datum', name: 'bis', label: 'Bis', pflicht: true }],
    knoepfe: [{ text: 'Speichern', art: 'neben' }] }] });
return [{ json: { inhalt: { seite: kopf, abschnitte, fenster: [] } } }];

parameters.query:
-- Beitrag laden (ALLY 25, Punkt 5a, Stefan 21.10.2026): ein Beitrag des Talents wie in ALLY 8 (talents_beitrag: Zahlen, Verlauf je Abruftag, Vergleich mit dem Schnitt,
-- Verfolgung; Recht am Talent prüft die Datenbank). Nur wenn ?beitrag= gesetzt ist, sonst NULL. Nur lesend. $1 Sitzung, $2 Beitrag.
SELECT CASE WHEN $1::text ~ '^[0-9a-f]{64}$' AND $2::text ~ '^[0-9]{1,12}$' THEN talents_beitrag($1::text, $2::text::bigint) END AS bt;

parameters.jsCode:
// Seite ergänzen (ALLY 25, Ladezeit Stefan 21.10.2026): die neun Ergänzungs-Knoten nach „Seite beschreiben“ in einem Knoten (je Code-Knoten kostet n8n etwa 20 ms).
// Jeder Schritt ist der bisherige Knoten-Code unverändert, in derselben Reihenfolge und mit derselben Eingabe; $('<Name>') eines früheren Schritts liefert dessen Ergebnis.
// Reihenfolge: Werkzeug-Links, Download-Links (Eingabe „Reports laden“), Datenimport-Link, Kopf-Metazeile, Content-Galerie, Profil wie ALLY 8 (Eingabe „Beitrag laden“),
// Links in neuem Tab, Verbindungen in Einstellungen, Einstellungen des Talents, Daten jetzt abrufen (Migration 194), Content-Seite und Kacheln (Plan 62).
const $n8n = $;
const MERK = {};
const als = arr => ({ first: () => ({ json: arr[0] }), last: () => ({ json: arr[arr.length - 1] }), all: () => arr.map(json => ({ json })), item: { json: arr[0] }, isExecuted: true });
const $merk = name => Object.prototype.hasOwnProperty.call(MERK, name) ? als(MERK[name]) : $n8n(name);
// Der Task-Runner von n8n gibt dem Code nur die Daten der Knoten mit, die im Code als $('Name') vorkommen; die drei Eingaben daher hier ausdrücklich.
const VORHER = { 'Seite beschreiben': $('Seite beschreiben').all().map(x => x.json), 'Reports laden': $('Reports laden').all().map(x => x.json), 'Beitrag laden': $('Beitrag laden').all().map(x => x.json) };
const eingabe = name => Object.prototype.hasOwnProperty.call(MERK, name) ? MERK[name] : VORHER[name];
const SCHRITT = {};
// ===== Schritt: Werkzeug-Links (bisher eigener Knoten; Eingabe: Seite beschreiben) =====
SCHRITT["Werkzeug-Links"] = async ($input, $) => {
// Werkzeug-Links (ALLY 25, BA10 Teil 3, Migration 71, Stefan 20.10.2026): ergänzt das fertige Talent-Profil, ohne „Seite beschreiben“ zu ändern.
// 1. Abschnitt „Strategie und Kommunikation“ mit den KI-Werkzeugen des Talents (Content-Strategie, Content-Insights, Brand-Matching, Korrespondenz, Textentwürfe; Seite talent mit w=…).
// 2. Content: Verfolgung je Beitrag ändern wie ALLY 8 (tb_verfolgung: Standard, eigene Dauer in Tagen, unbegrenzt), nur mit dem Recht dafür (darf_verwalten der Beiträge); Storys immer 24 Stunden.
const aus = $input.all().map(x => x.json);
const E = $('Start').first().json;
const D = $('Daten laden').first().json || {};
const T = D.t || {};
const id = Number((T.talent || {}).id);
const WZ = [['konzept', 'Content-Strategie', 'Positionierung, Ziele mit Soll/Ist, Format-Mix und Themenplan'], ['wf', 'Content-Insights', 'Was überdurchschnittlich funktioniert, Vorschläge der KI'],
  ['marken', 'Brand-Matching', 'Passende Marken für Kooperationen'], ['mails', 'Korrespondenz', 'Mails mit dem Talent und Mail-Entwürfe'], ['texte', 'Textentwürfe', 'Mediakit, Kampagnenbericht, Antworten an Marken']];
for (const j of aus) {
  const I = j && j.inhalt;
  if (!I || typeof I !== 'object' || !Array.isArray(I.abschnitte) || T.ok !== true || !(id > 0)) continue;
  if (!I.abschnitte.some(a => a && a.id === 'werkzeuge')) {
    const i = I.abschnitte.findIndex(a => a && a.id === 'kampagnen');
    I.abschnitte.splice(i < 0 ? I.abschnitte.length : i + 1, 0, { id: 'werkzeuge', titel: 'Strategie und Kommunikation', zahl: String(WZ.length), offen_standard: false,
      info: 'Die KI arbeitet nur, wenn du in einem Werkzeug ausdrücklich einen Vorschlag anforderst. Das zählt zum KI-Budget.',
      inhalt: [{ typ: 'liste', eintraege: WZ.map(w => ({ fett: w[1], text: w[2], ziel: { seite: 'talent', parameter: { id, w: w[0] } }, ziel_text: 'Öffnen' })) }] });
  }
  // Verfolgung je Beitrag (nur Zeilen der gezeigten Seite, gleiche Auswahl wie „Seite beschreiben“)
  const C = D.content || { anzahl: 0, zeilen: [] };
  const JE = 20, cGes = Number(C.anzahl) || 0, cSeiten = Math.max(1, Math.ceil(cGes / JE)), cSeite = Math.min(cSeiten, Math.max(1, Number((E.seiten || {}).content) || 1));
  const roh = (C.zeilen || []).filter(z => z.i > (cSeite - 1) * JE && z.i <= cSeite * JE).map(z => z.b || {});
  const ab = I.abschnitte.find(a => a && a.id === 'content');
  const tab = ab && Array.isArray(ab.inhalt) ? ab.inhalt.find(b => b && b.typ === 'tabelle' && b.id === 'content') : null;
  const darf = T.darf_verwalten === true;
  if (!tab || !Array.isArray(tab.zeilen) || tab.zeilen.length !== roh.length || !darf) continue;
  I.fenster = Array.isArray(I.fenster) ? I.fenster : [];
  tab.zeilen.forEach((z, k) => {
    const b = roh[k], bid = /^[0-9]{1,12}$/.test(String(b.id ?? '')) ? String(b.id) : '', vf = b.verfolgung || {};
    if (!bid || vf.story === true || !z.zellen) return;
    const e = String(vf.einstellung || 'standard'), tage = /^[0-9]{1,4}$/.test(e) && e !== '0' ? e : '';
    const gesetzt = tage ? 'tage' : e === 'unbegrenzt' || e === '0' ? 'unbegrenzt' : 'standard';
    z.zellen.verfolgung = { text: String(vf.text || 'Verfolgung'), fenster: 'verfolgung-' + bid };
    I.fenster.push({ id: 'verfolgung-' + bid, art: 'dialog', titel: 'Verfolgung für diesen Beitrag', untertitel: [b.erstellt, b.art_name, b.konto].filter(Boolean).join(' · '), inhalt: [
      { typ: 'text', ton: 'grau', text: String(vf.text ? vf.text.charAt(0).toUpperCase() + vf.text.slice(1) : '–') + (vf.quelle === 'beitrag' ? ' (eigene Einstellung für diesen Beitrag)'
        : vf.quelle === 'talent' ? ' (Einstellung des Talents)' : vf.quelle === 'agentur' ? ' (Standard der Agentur)' : '') },
      { typ: 'formular', id: 'verfolgung-' + bid, aktion: 'tb_verfolgung', werte: { beitrag: bid, talent: String(id) }, spalten: 2,
        info: 'Läuft die Dauer noch, werden die Zahlen wieder jede Nacht geholt. Ist sie schon vorbei, bleiben die Zahlen auf dem letzten Stand.',
        felder: [{ typ: 'auswahl', name: 'verfolgung_art', label: 'Verfolgung', wert: gesetzt, optionen: [{ wert: 'standard', text: String(vf.standard_text || 'Standard') },
          { wert: 'tage', text: 'Eigene Dauer in Tagen' }, { wert: 'unbegrenzt', text: 'Unbegrenzt' }] },
          { typ: 'zahl', name: 'verfolgung_tage', label: 'Tage ab Veröffentlichung', wert: tage, min: 1, max: 3650, schritt: 1, info: 'Nur bei „Eigene Dauer in Tagen“.' }],
        knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Speichern' }] }] });
  });
}
return aus.map(json => ({ json }));
};

// ===== Schritt: Download-Links (bisher eigener Knoten; Eingabe: Reports laden) =====
SCHRITT["Download-Links"] = async ($input, $) => {
// Download-Links (ALLY 25, BA10 Teil 4, Stefan 21.10.2026): ergänzt das Talent-Profil, ohne „Seite beschreiben“ und „Werkzeug-Links“ zu ändern:
// 1. Kopf › Aktionen „Export (ZIP)“ wie ALLY 8 (nur mit dem Recht, das Talent zu verwalten), 2. Abschnitt „Reports“ mit den erzeugten Reports des Talents und „Herunterladen“.
// Downloads nur über Ally (Seite datei mit tx bzw. tr; ALLY 20 prüft Rechte und holt die Datei), nie ein Direktlink.
const aus = $('Werkzeug-Links').all().map(x => x.json);
const D = $('Daten laden').first().json || {};
const T = D.t || {};
const id = Number((T.talent || {}).id);
const B = ($input.first().json || {}).b;
for (const j of aus) {
  const I = j && j.inhalt;
  if (!I || typeof I !== 'object' || !Array.isArray(I.abschnitte) || T.ok !== true || !(id > 0)) continue;
  if (T.darf_verwalten === true && I.seite && typeof I.seite === 'object') {
    I.seite.aktionen = (Array.isArray(I.seite.aktionen) ? I.seite.aktionen : []).concat([{ text: 'Export (ZIP)', ziel: { seite: 'datei', parameter: { tx: String(id) } } }]);
  }
  if (B && typeof B === 'object' && Array.isArray(B.zeilen) && !I.abschnitte.some(a => a && a.id === 'reports')) {
    const Z = B.zeilen.filter(x => x && /^[0-9]{1,12}$/.test(String(x.id)));
    const i = I.abschnitte.findIndex(a => a && a.id === 'werkzeuge');
    I.abschnitte.splice(i < 0 ? I.abschnitte.length : i + 1, 0, { id: 'reports', titel: 'Reports', zahl: String(B.anzahl ?? Z.length), offen_standard: false,
      info: 'Erzeugte Reports dieses Talents, die zehn neuesten. Erstellen und alle Reports unter Reports; regelmäßige Reports liegen zusätzlich im Speicherort.',
      inhalt: [{ typ: 'tabelle', id: 'reports', titel: 'Reports', spalten: [{ schluessel: 'titel', titel: 'Report' }, { schluessel: 'art', titel: 'Art und Zeitraum' },
        { schluessel: 'erstellt', titel: 'Erstellt' }, { schluessel: 'datei', titel: 'Datei' }],
        zeilen: Z.map(x => ({ zellen: { titel: { text: String(x.titel || ''), fett: true }, art: [x.art_name, x.zeitraum_text].filter(Boolean).join(' · ') || '–',
          erstellt: [x.erstellt_text, x.erstellt_von_name].filter(Boolean).join(' · ') || '–',
          datei: x.status === 'fertig' ? { text: 'Herunterladen', ziel: { seite: 'datei', parameter: { tr: String(x.id), t: String(id) } } } : String(x.status_text || '–') } })),
        sortierung: {}, seite: 1, je_seite: Math.max(1, Z.length), gesamt: Z.length, leer: 'Noch keine Reports für dieses Talent.' },
      // 7h (Stefan 24.10.2026, 16:52 Punkt 9; 25.10.2026 über den Koordinator): „Report erstellen“ in der Kachel: Dialog mit diesem Talent vorbelegt.
      // Plan 62 (K5): nur noch hier – die Hauptaktion „Report erstellen“ im Kopf (2c-2) ist entfallen.
      { typ: 'aktion', text: 'Report erstellen', ziel: { seite: 'talent-reports', parameter: { talent: id, f: 'neu' } } }] });
  }
}
return aus.map(json => ({ json }));
};

// ===== Schritt: Datenimport-Link (bisher eigener Knoten; Eingabe: Download-Links) =====
SCHRITT["Datenimport-Link"] = async ($input, $) => {
// Datenimport-Link (ALLY 25, BA10 Teil 4, Stefan 21.10.2026): ergänzt das Talent-Profil, ohne die übrigen Knoten zu ändern: im Abschnitt „Daten und Notizen“
// der Link zu Daten › Datenimport (Zahlen per Screenshot hochladen, prüfen und bestätigen; Seite talent mit w=zahlen), wie der Reiter in ALLY 8.
const aus = $input.all().map(x => x.json);
const T = ($('Daten laden').first().json || {}).t || {};
const id = Number((T.talent || {}).id);
for (const j of aus) {
  const I = j && j.inhalt;
  const a = I && Array.isArray(I.abschnitte) ? I.abschnitte.find(x => x && x.id === 'daten') : null;
