    if (BT.darf_verfolgung_aendern === true) {
      const OP = L(BT.verfolgung_optionen).length ? BT.verfolgung_optionen : [{ schluessel: 'standard', name: 'Standard' }, { schluessel: 'tage', name: 'Eigene Dauer in Tagen' }, { schluessel: 'unbegrenzt', name: 'Unbegrenzt' }];
      const e = s(vf.einstellung || 'standard'), tage = /^[0-9]{1,4}$/.test(e) && e !== '0' ? e : '';
      const gesetzt = tage ? 'tage' : e === 'unbegrenzt' || e === '0' ? 'unbegrenzt' : 'standard';
      vInhalt.push({ typ: 'formular', id: 'verfolgung', aktion: 'tb_verfolgung', werte: { beitrag: s(b.id), talent: String(id) }, spalten: 2,
        felder: [{ typ: 'auswahl', name: 'verfolgung_art', label: 'Verfolgung', wert: gesetzt, optionen: OP.map(o => ({ wert: s(o.schluessel), text: s(o.name) })),
          info: 'Läuft die Dauer noch, werden die Zahlen wieder jede Nacht abgerufen. Ist sie schon vorbei, bleiben die Zahlen auf dem letzten Stand.' },
          { typ: 'zahl', name: 'verfolgung_tage', label: 'Tage ab Veröffentlichung', wert: tage, min: 1, max: 3650, info: 'Nur bei „Eigene Dauer in Tagen“.' }],
        knoepfe: [{ text: 'Speichern', art: 'neben' }] });
    } else if (vf.story) vInhalt.push({ typ: 'text', ton: 'grau', text: 'Storys werden immer 24 Stunden verfolgt.' });
    abschnitte.push({ id: 'b-verfolgung', titel: 'Verfolgung für diesen Beitrag', offen_standard: true, info: ['Wie lange die Zahlen dieses Beitrags täglich abgerufen werden.'], inhalt: vInhalt });
    j.inhalt = Object.assign({ seite, ueberblick, abschnitte }, I.hinweis ? { hinweis: I.hinweis } : {});
    continue;
  }

  // ---------- 5d: Kennzahlen im Überblick ----------
  const U = I.ueberblick;
  if (U && typeof U === 'object' && L(T.kennzahlen).length) {
    const kz = L(T.kennzahlen).map(k => {
      const label = s(k.name || k.schluessel) + (k.manuell === true ? ' (manuell)' : '');
      if (k.schluessel === 'follower') { const zu = k.zuwachs || {};
        return Object.assign({ label, wert: wt(k), neben: k.manuell === true && k.quelle_text ? s(k.quelle_text) : '' },
          !(k.manuell === true && k.quelle_text) && zu.text ? { trend: { text: s(zu.text) + ' im Zeitraum', richtung: Number(zu.wert) > 0 ? 'hoch' : Number(zu.wert) < 0 ? 'runter' : 'gleich' } }
            : !(k.manuell === true && k.quelle_text) && k.zusatz ? { neben: s(k.zusatz) } : {}); }
      const v = k.veraenderung || {}, vo = k.vorher && k.vorher.wert !== null && k.vorher.wert !== undefined ? 'vorher ' + wt(k.vorher) : '';
      if (k.manuell === true && k.quelle_text) return { label, wert: wt(k), neben: s(k.quelle_text) };
      return Object.assign({ label, wert: wt(k), neben: vo },
        v.text && v.text !== '–' ? { trend: { text: s(v.text), richtung: RI(v.richtung) } } : {});
    });
    U.kennzahlen = kz;
    // Zeitraum, Vergleichszeitraum und Datenstand wie in ALLY 8 als graue Zeile unter „Überblick“ (Baukasten ueberblick.unter)
    const zt = [zr.text, zr.vor_text, (T.datenstand || {}).text].filter(Boolean).map(s).join(' · ');
    if (zt) U.unter = zt;
    if (T.abgeleitet === true && T.abgeleitet_text) U.info = L(U.info).concat(['* ' + s(T.abgeleitet_text)]);
  }

  // ---------- 5i: Einladungslink im Überblick zum Kopieren (wie ALLY 24) ----------
  const J = D.j || null, verw = T.darf_verwalten === true || (D.r && D.r.talent === true), ei = J && J.einladung;
  if (U && verw && ei && ei.abgelaufen !== true && ei.link) {
    const acc = L(U.karten).find(k => k && k.titel === 'Accounts');
    const e = acc ? L(acc.eintraege).find(x => x && x.text === 'Einladungslink') : null;
    if (e) {
      const tx = ei.text && typeof ei.text === 'object' && ei.text.text ? ei.text : null;
      const neu = e.aktion;
      e.aktion = { text: 'Link und Text', fenster: 'einladung' };
