      if (tx) felder.push({ typ: 'anzeige', name: 'betreff', label: 'Betreff', wert: s(tx.betreff), kopieren: true, breite: 'voll' },
        Object.assign({ typ: 'anzeige', name: 'text', label: 'Einladungstext', wert: s(tx.text), kopieren: true, mehrzeilig: true, breite: 'voll' },
          tx.an ? {} : { info: 'Für dieses Talent ist keine E-Mail-Adresse hinterlegt. Die Empfängeradresse im Mailprogramm eintragen.' }));
      const inhalt = [{ typ: 'formular', id: 'einladung', felder }];
