    if (BB.length) inhalt.push({ typ: 'galerie', id: 'top', titel: 'Top-Content', bild_leer: 'Keine Vorschau', karten: BB.map(karte) });
    else inhalt.push({ typ: 'text', ton: 'grau', text: s(T.beste_hinweis || 'Keine Beiträge in diesem Zeitraum.') });
    inhalt.push({ typ: 'aktion', text: 'Gesamten Content anzeigen (' + (Number(T.anzahl_beitraege) || 0) + ')', art: 'link', ziel: hier('a-content') });
    perf.inhalt = inhalt;
  }

  // ---------- 5g: Kachel Audience ----------
  // Plan 63 (Stefan 01.11.2026, 17:13: „hier im Dropdown gibt es viele Kategorien mehrfach … Ein Dropdown für die Kategorien und ein weiteres Dropdown für den Kanal.
  // Dann, wenn ich als Kategorie z. B. Alter auswähle und nur einen Kanal, dann passt die horizontale Balkendarstellung. Schalte ich mehr als einen Kanal ein, sollen sie
  // wechseln in vertikale Darstellung und nebeneinander für einen sinnvollen Vergleich. Zudem soll die Audience eine eigene Kachel direkt rechts neben der Performance
  // sein.“; Entscheidung: Kategorie auch mehrfach): feste Kachel „Audience“ (Regel festeKacheln der Web-App, nach „Performance“) mit dem Baustein „vergleich“:
  // Mehrfachauswahl „Kategorie“ (Aufteilung: Alter, Geschlecht, Land, Stadt – je einmal) und „Kanal“ (Account, bei Instagram mit Follower und Interagierenden Konten
  // je ein Eintrag); je gewählter Kategorie eine Grafik – ein Kanal: waagrechte Balken wie bisher (inhalt, höchstens 10 Einträge, „und n weitere“), mehrere Kanäle:
  // Säulen je Eintrag nebeneinander (Anteil in Prozent je Kanal). Start = erste Kategorie und erster Kanal (= Kurzansicht in „Performance“). Daten wie bisher.
  // Plan 63c (Stefan 01.11.2026, 17:43 „dann bitte immer waagerechte gruppen“): mehrere Kanäle ebenfalls waagrecht – je Eintrag der Name, darunter je Kanal ein Balken
  // in der Farbe des Kanals mit Wert, Legende mit den Kanälen (Web-App, Grafik „gruppiert“); keine Säulen mehr.
  I.abschnitte = AB.filter(a => !(a && a.id === 'audience'));
  if (perf) {
    const ART = { follower_demographics: 'Follower', engaged_audience_demographics: 'Interagierende Konten', viewer_demographics: 'Zuschauer' };
    const KAT = { age: 'Alter', gender: 'Geschlecht', country: 'Land', city: 'Stadt' }, KO = ['age', 'gender', 'country', 'city'];
    const KA = L(T.kanaele);
    const katVon = g => s(g.aufteilung) || s(g.art);
    const reiheVon = g => s(g.kanal_id) + ':' + s(g.gruppe);
    const rang = k => KO.includes(k) ? KO.indexOf(k) : KO.length;
    const kats = [...new Set(ZG.map(katVon))].sort((a, b) => rang(a) - rang(b));
    const reihen = [...new Set(ZG.map(reiheVon))];
    const mehrere = ZG.some(x => x.plattform !== (ZG[0] || {}).plattform);
    const reiheText = r => { const g = ZG.find(x => reiheVon(x) === r) || {}, k = KA.find(x => s(x.kanal_id) === s(g.kanal_id)) || {};
      const zweiAccounts = new Set(ZG.filter(x => x.plattform === g.plattform).map(x => s(x.kanal_id))).size > 1;
      const zweiArten = new Set(ZG.filter(x => s(x.kanal_id) === s(g.kanal_id)).map(x => s(x.gruppe))).size > 1;
      return [s(g.plattform_name), zweiAccounts ? s(k.extern_name || k.name) : '', zweiArten ? s(ART[g.gruppe] || g.gruppe) : ''].filter(Boolean).join(' · '); };
    const katText = k => KAT[k] || s(((ZG.find(x => katVon(x) === k) || {}).name || k).split(' nach ').pop());
    const zahlText = (n, eins, mehr) => n + ' ' + (n === 1 ? eins : mehr);
    const hinweis = s(T.zielgruppe_hinweis || 'Die Zielgruppe zeigt Instagram erst ab 100 Followern.');
    I.abschnitte.push({ id: 'audience', titel: 'Audience', offen_standard: false,
      zahl: ZG.length ? zahlText(kats.length, 'Kategorie', 'Kategorien') + ' · ' + zahlText(reihen.length, 'Kanal', 'Kanäle') : '',
      info: ZG.length ? ['Kategorie und Kanal sind mehrfach wählbar; je Kategorie eine Grafik. Ein Kanal: ein Balken je Eintrag. Mehrere Kanäle: je Eintrag ein Balken je Kanal untereinander zum Vergleich (Farbe wie in der Legende, Anteil in Prozent je Kanal). Je Kanal und Kategorie höchstens 10 Einträge.', hinweis] : [hinweis],
      inhalt: ZG.length ? [{ typ: 'vergleich', id: 'audience', hoechstens: 10, leer: 'Bitte mindestens eine Kategorie und einen Kanal wählen.',
        kategorie: { typ: 'mehrfach', liste: true, name: 'kategorie', label: 'Kategorie', platzhalter: 'Keine Kategorie', einheit: 'Kategorien', wert: [katVon(ZG[0])],
          optionen: kats.map(k => Object.assign({ wert: k, text: katText(k) }, k === 'age' ? { ordnung: 'schluessel' } : {})) },
        reihe: { typ: 'mehrfach', liste: true, name: 'kanal', label: 'Kanal', platzhalter: 'Kein Kanal', einheit: 'Kanäle', wert: [reiheVon(ZG[0])],
          optionen: reihen.map(r => ({ wert: r, text: reiheText(r) })) },
        daten: ZG.map((g, i) => ({ kategorie: katVon(g), reihe: reiheVon(g), name: reiheText(reiheVon(g)), titel: gTitel(g, mehrere), stand: s(g.stand),
          inhalt: balken(g, 'zg-' + i),
          werte: L(g.eintraege).map(e => ({ schluessel: s(e.schluessel || e.name), text: s(e.name || e.schluessel), wert: Number(e.anteil) || 0, wert_text: s(e.anteil_text || e.text) })) })) }]
        : [{ typ: 'text', ton: 'grau', text: 'Noch keine Angaben zur Audience.' }] });
  }

  // ---------- 5a: Galerie und Tabelle im Content führen zum Beitrag ----------
  const con = AB.find(a => a && a.id === 'content');
  const ga = con ? L(con.inhalt).find(b => b && b.typ === 'galerie' && b.id === 'content') : null;
  if (ga) {
    const C = D.content || { anzahl: 0, zeilen: [] };
    const JE = 20, cGes = Number(C.anzahl) || 0, cSeiten = Math.max(1, Math.ceil(cGes / JE)), cSeite = Math.min(cSeiten, Math.max(1, Number((E.seiten || {}).content) || 1));
    const roh = L(C.zeilen).filter(z => z.i > (cSeite - 1) * JE && z.i <= cSeite * JE).map(z => z.b || {});
    if (L(ga.karten).length === roh.length) ga.karten.forEach((k, i) => { const zb = zumBeitrag(roh[i].id); if (zb) k.titel_ziel = zb; });
    const tz = ga.tabelle && L(ga.tabelle.zeilen);
    if (tz && tz.length === roh.length) tz.forEach((z, i) => { const zb = zumBeitrag(roh[i].id), c = z && z.zellen;
      if (zb && c) c.erstellt = { text: typeof c.erstellt === 'object' && c.erstellt ? s(c.erstellt.text) : s(c.erstellt), ziel: zb }; });
  }
}
return aus.map(json => ({ json }));
};

// ===== Schritt: Links in neuem Tab (bisher eigener Knoten; Eingabe: Profil wie ALLY 8) =====
SCHRITT["Links in neuem Tab"] = async ($input, $) => {
// Links in neuem Tab (ALLY 25, Abnahme-Korrektur, Stefan 21.10.2026): Links zum Beitrag auf der Plattform (geprüfte Seite „link“, Art b) öffnen in einem neuen Tab
// und tragen den Pfeil für fremde Seiten. Der Baukasten (ALLY 21) zeichnet das für Ziele mit neuer_tab. Sonst bleibt alles unverändert.
const ARTEN = ['b'];
const markiere = x => {
  if (Array.isArray(x)) { x.forEach(markiere); return; }
  if (!x || typeof x !== 'object') return;
  for (const k of Object.keys(x)) {
    const v = x[k];
    if (v && typeof v === 'object' && !Array.isArray(v) && v.seite === 'link' && v.parameter && ARTEN.includes(String(v.parameter.art || ''))) v.neuer_tab = true;
    else markiere(v);
  }
};
const aus = $input.all().map(x => x.json);
for (const j of aus) if (j && j.inhalt) markiere(j.inhalt);
return aus.map(json => ({ json }));
};

// ===== Schritt: Verbindungen in Einstellungen (bisher eigener Knoten; Eingabe: Links in neuem Tab) =====
SCHRITT["Verbindungen in Einstellungen"] = async ($input, $) => {
// Verbindungen in Einstellungen (ALLY 25, Stefan 21.10.2026, 14:13/14:14/14:18): ergänzt das fertige Talent-Profil, ohne die Knoten davor zu ändern.
// 1. Die Karte „Accounts“ (alle Verbindungen mit Stand, „gültig bis“, „Trennen“, Einladungslink) gehört nicht in die Arbeitsansicht: Sie kommt aus dem Überblick
//    in das Fenster „Einstellungen“ des Talents, das das Zahnrad im Profilkopf öffnet (nur mit dem Recht, das Talent zu verwalten; Rechte wie bisher).
//    Ohne dieses Recht bleibt das Zahnrad wie bisher bei „Einstellungen für Talents“.
// 2. Plattform-Symbole in eigener Zelle (Baukasten seite.plattformen) statt in der Metazeile: ein Symbol je Verbindung, mit Markierung bei Handlungsbedarf
//    (Warnung der Datenbank, nicht verbunden, abgelaufen oder gültig nur noch 14 Tage). Ein Klick öffnet die Verbindungen (mit Recht).
// 3. Content öffnet sich auf einer eigenen Seite: Link unter Top-Content und Krümelpfad bzw. „Zum Content“ der Beitragsseite (Plan 62: content=1, siehe unten).
const aus = $input.all().map(x => x.json);
const E = $('Start').first().json;
const P = E.parameter || {};
const D = $('Daten laden').first().json || {};
const T = D.t || {};
const s = v => String(v ?? '');
const L = x => Array.isArray(x) ? x : [];
const id = Number((T.talent || {}).id);
const verw = T.darf_verwalten === true || (D.r && D.r.talent === true);
const jetzt = new Date();
const heute = Date.UTC(jetzt.getUTCFullYear(), jetzt.getUTCMonth(), jetzt.getUTCDate());
const tageBis = d => { const m = /^([0-9]{2})\.([0-9]{2})\.([0-9]{4})$/.exec(s(d)); return m ? Math.round((Date.UTC(+m[3], +m[2] - 1, +m[1]) - heute) / 86400000) : null; };
// Plan 62 (P3; Stefan 21.10.2026, 14:18: „Alle anzeigen“ / „Gesamten Content anzeigen“ öffnet eine eigene Seite, entschieden 21.10.): die Links führen auf die eigene
// Content-Seite = Talent-Profil mit content=1 (Schritt „Content-Seite und Kacheln“). Damit gilt weder ?alle=content (alter Baukasten, ohne Wirkung) noch der Sprung
// zum Abschnitt im Profil (2c-3, Anker a-content). Filter des Profils (Zeitraum, Account, manuelle Daten) bleiben erhalten; „Account“ wirkt auf die Beiträge.
const FILTER = {}; for (const k of ['zeitraum', 'von', 'bis', 'kanal', 'manuell']) if (P[k]) FILTER[k] = s(P[k]);
const zumContent = () => ({ seite: 'talent', parameter: Object.assign({ id: String(id) }, FILTER, { content: '1' }) });
const istContentZiel = z => z && typeof z === 'object' && z.seite === 'talent' && z.anker === 'a-content';
// Links „Gesamten Content anzeigen“, „Zum Content“ und Krümel „Content“ (in den Schritten davor Anker a-content) auf die eigene Content-Seite
const umlenken = x => { if (Array.isArray(x)) { x.forEach(umlenken); return; } if (!x || typeof x !== 'object') return;
  for (const k of Object.keys(x)) { const v = x[k]; if (k === 'ziel' && istContentZiel(v)) x[k] = zumContent(); else umlenken(v); } };
for (const j of aus) {
  const I = j && j.inhalt, S = I && I.seite;
  if (!S || typeof S !== 'object' || S.schluessel !== 'talent' || T.ok !== true || !(id > 0)) continue;
  umlenken(I);
  if (!S.avatar) continue; // nur das Profil selbst (nicht Beitrag oder Werkzeug)
  const TA = T.talent || {}, name = s(TA.anzeigename || TA.name || ('Talent ' + id)), kan = L(T.kanaele);
  const warn = {}; for (const w of L(T.warnungen)) (warn[w.kanal_id] = warn[w.kanal_id] || []).push(w);
  S.plattformen = kan.map(k => {
    const w = L(warn[k.kanal_id]).find(x => x && x.stufe === 'warnung'), tb = tageBis(k.gueltig_bis), nicht = !!k.status && k.status !== 'verbunden';
    const hinweis = w ? s(w.text) : nicht ? s(k.status_text || k.status) : tb !== null && tb < 0 ? 'abgelaufen' : tb !== null && tb <= 14 ? 'gültig bis ' + s(k.gueltig_bis) : '';
    return Object.assign({ schluessel: s(k.plattform), name: s(k.name), text: k.text && k.text !== k.name ? s(k.text) : '', hinweis, warn: !!hinweis }, verw ? { fenster: 'verbindungen' } : {});
  });
  if (S.meta && typeof S.meta === 'object') delete S.meta.plattformen;
  const U = I.ueberblick;
  const ki = U ? L(U.karten).findIndex(c => c && c.titel === 'Accounts') : -1;
  const acc = ki >= 0 ? U.karten.splice(ki, 1)[0] : null;
  if (verw) {
    const inhalt = [{ typ: 'unterueberschrift', text: 'Accounts und Verbindungen', info: acc && acc.info ? acc.info : undefined },
      { typ: 'liste', leer: s((acc && acc.leer) || 'Keine Accounts.'), eintraege: acc ? L(acc.eintraege) : [], vorschau: false }];
    if (S.zahnrad && S.zahnrad.ziel) inhalt.push({ typ: 'aktion', art: 'link', text: 'Einstellungen für alle Talents', ziel: S.zahnrad.ziel });
    I.fenster = L(I.fenster).concat([{ id: 'verbindungen', art: 'seitenfenster', titel: 'Einstellungen', untertitel: name, avatar: S.avatar, inhalt }]);
    S.zahnrad = { fenster: 'verbindungen', label: 'Einstellungen von ' + name };
  }
}
return aus.map(json => ({ json }));
};

// ===== Schritt: Einstellungen des Talents (bisher eigener Knoten; Eingabe: Verbindungen in Einstellungen) =====
SCHRITT["Einstellungen des Talents"] = async ($input, $) => {
// Einstellungen des Talents (ALLY 25, Stefan 21.10.2026, 19:38, Abnahme Punkt 57): ergänzt das fertige Talent-Profil, ohne die Knoten davor zu ändern.
// Im Profil (Arbeitsansicht) steht keine Verwaltung mehr. Die Abschnitte „Verbindungen“ (bisher Fenster „Einstellungen“) und „Talent-Bereich“ (Zugang, Briefing,
// Sichtbarkeit, Ally-Chat, Ordner im Speicherort) stehen auf einer eigenen Seite: Talent-Profil mit Parameter einstellungen=1, Krümelpfad Startseite › Talents › Name › Einstellungen.
// Das Zahnrad im Profilkopf und die Plattform-Symbole führen dorthin, wenn die Person mindestens einen der beiden Abschnitte sehen darf (Rechte wie bisher:
// Verbindungen nur mit dem Recht, das Talent zu verwalten; Talent-Bereich nur mit dem Recht „Talent-Zugang und Talent-Bereich einstellen“). Ohne beides bleibt das Zahnrad
// bei „Einstellungen für Talents“, und einstellungen=1 zeigt das normale Profil. Links innerhalb der Abschnitte (Ordner durchsuchen, Ebene höher, Umbenennen) bleiben auf der neuen Seite.
// Plan 62 (T6; Stefan 24.10.2026, 16:52 Punkt 10: „gehört auf die Profilseite … nicht versteckt in die Einstellungen“; 25.10.2026, 14:05 „Beides“): „Verbindungen“
// steht zusätzlich als Kachel im Profil – derselbe Abschnitt (Inhalt, Aktionen, i) wie auf der Einstellungsseite, Rechte wie bisher.
const aus = $input.all().map(x => x.json);
const E = $('Start').first().json;
const P = E.parameter || {};
const D = $('Daten laden').first().json || {};
const T = D.t || {};
const s = v => String(v ?? '');
const L = x => Array.isArray(x) ? x : [];
const id = Number((T.talent || {}).id);
// Ordner durchsuchen (ob=1) gehört zum Talent-Bereich und damit immer auf diese Seite, auch bei älteren Links ohne einstellungen=1
const aufSeite = s(P.einstellungen) === '1' || s(P.ob) === '1';
// Filter des Profils (Zeitraum, Account, manuelle Daten) bleiben beim Wechsel zwischen Profil und Einstellungen erhalten
const filter = {}; for (const k of ['zeitraum', 'von', 'bis', 'kanal', 'manuell']) if (P[k]) filter[k] = s(P[k]);
const zumProfil = () => ({ seite: 'talent', parameter: Object.assign({ id: String(id) }, filter) });
const zuEinstellungen = anker => Object.assign({ seite: 'talent', parameter: Object.assign({ id: String(id) }, filter, { einstellungen: '1' }) }, anker ? { anker } : {});
