const ANKER = new Set(['a-talent-bereich', 'a-verbindungen']);
const aufDieseSeite = x => { if (Array.isArray(x)) { x.forEach(aufDieseSeite); return; } if (!x || typeof x !== 'object') return;
  for (const k of Object.keys(x)) { const v = x[k];
    if ((k === 'ziel' || k === 'zurueck_ziel') && v && typeof v === 'object' && v.seite === 'talent' && ANKER.has(v.anker))
      x[k] = Object.assign({}, v, { parameter: Object.assign({}, v.parameter || {}, { einstellungen: '1' }) });
    else aufDieseSeite(v); } };
const res = [];
for (const j of aus) {
  const I = j && j.inhalt, S = I && I.seite;
  if (!S || typeof S !== 'object' || S.schluessel !== 'talent' || T.ok !== true || !(id > 0) || !S.avatar) { res.push(j); continue; }
  const name = s(S.titel);
  const AB = L(I.abschnitte);
  const ti = AB.findIndex(a => a && a.id === 'talent-bereich');
  const tb = ti >= 0 ? AB.splice(ti, 1)[0] : null;
  const FE = L(I.fenster);
  const vi = FE.findIndex(f => f && f.id === 'verbindungen');
  const vf = vi >= 0 ? FE.splice(vi, 1)[0] : null;
  I.abschnitte = AB; I.fenster = FE;
  const darf = !!(tb || vf);
  if (!darf) { res.push(j); continue; }
  // Abschnitt „Verbindungen“ aus dem bisherigen Fenster (Zwischenüberschrift → i des Abschnitts); Einstellungsseite und Kachel im Profil (Plan 62) gleich
  const verbindungen = () => { const inh = L(vf.inhalt).slice();
    const kopf = inh.length && inh[0] && inh[0].typ === 'unterueberschrift' ? inh.shift() : null;
    return { id: 'verbindungen', titel: 'Verbindungen', offen_standard: true, info: kopf && kopf.info ? kopf.info : undefined, inhalt: inh }; };
  if (!aufSeite) {
    // Profil: Zahnrad und Symbole führen zur eigenen Seite
    S.zahnrad = { ziel: zuEinstellungen(), label: 'Einstellungen von ' + name };
    for (const p of L(S.plattformen)) if (p && p.fenster === 'verbindungen') { delete p.fenster; p.ziel = vf ? zuEinstellungen('a-verbindungen') : undefined; }
    // Plan 62 (T6): Kachel „Verbindungen“ im Profil (feste Kachel, Regel festeKacheln der Web-App)
    if (vf) I.abschnitte.push(verbindungen());
    res.push(j); continue;
  }
  // Eigene Seite „Einstellungen“ des Talents
  const abschnitte = [];
  if (vf) abschnitte.push(verbindungen());
  if (tb) abschnitte.push(Object.assign({}, tb, { offen_standard: true }));
