  const krumen = L(S.krumen).slice(0, -1).concat([{ text: name, ziel: zumProfil() }, { text: 'Einstellungen' }]);
  const seite = { schluessel: 'talent', art: S.art || 'funktion', titel: 'Einstellungen', beschreibung: name, avatar: S.avatar, krumen, zustand_teil: 'einstellungen' };
  const neu = { seite, abschnitte, fenster: FE };
  if (I.hinweis) neu.hinweis = I.hinweis;
  res.push(Object.assign({}, j, { inhalt: neu }));
}
return res.map(json => ({ json }));
};
