SCHRITT["Daten jetzt abrufen"] = async ($input, $) => {
// Daten jetzt abrufen (ALLY 25, Migration 194, Stefan 01.11.2026): Knopf im Abschnitt „Performance“ des Talent-Profils. Startet über ALLY 20 (tl_daten_abrufen,
// talents_sofortabruf_ui_aktion) den Abruf aller abrufbaren Kanäle nur dieses Talents, mit denselben Workflows wie nach der Einladung. Nur für Personen, die das
// Talent sehen dürfen („Abruf-Stand“). Läuft ein Abruf, ist der Knopf gesperrt („Abruf läuft …“, Muster aus/grund); ohne abrufbaren Kanal ebenso, mit Grund.
// Erklärung am i des Abschnitts (vorhandene Absätze bleiben). Keine Abfrage im Hintergrund: neue Zahlen nach dem Neuladen der Seite.
const aus = $input.all().map(x => x.json);
let SA = null;
try { const x = $('Abruf-Stand').first().json || {}; SA = x.sa && typeof x.sa === 'object' ? x.sa : null; } catch (e) { SA = null; }
const T = ($('Daten laden').first().json || {}).t || {};
const id = Number((T.talent || {}).id);
if (!SA || SA.ok !== true || !(id > 0)) return aus.map(json => ({ json }));
// Migration 195 (Stefan 01.11.2026, Abrufzeiten): die eingestellten Zeiten (Einstellungen › Social Media, talents_abrufzeit_text aus „Abruf-Stand“) statt fester Zeiten
let ZP = '';
try { ZP = String(($('Abruf-Stand').first().json || {}).zp || '').trim(); } catch (e) { ZP = ''; }
const INFO = 'Ally ruft die Daten automatisch ab: ' + (ZP || 'zu den Zeiten aus Einstellungen › Social Media') + '. Mit „Daten jetzt abrufen“ startet der Abruf sofort für dieses Talent. Der Abruf verursacht keine KI-Kosten.';
for (const j of aus) {
  const I = j && j.inhalt, S = I && I.seite;
  if (!I || typeof I !== 'object' || !S || S.schluessel !== 'talent' || !Array.isArray(I.abschnitte)) continue;
  const perf = I.abschnitte.find(a => a && a.id === 'performance');
  if (!perf) continue;
  const knopf = SA.laeuft === true
    ? { typ: 'aktion', text: 'Abruf läuft …', aus: true, grund: 'Ally ruft die Daten dieses Talents gerade ab. Neue Zahlen erscheinen nach dem Neuladen der Seite.' }
    : !(Number(SA.abrufbar) > 0)
      ? { typ: 'aktion', text: 'Daten jetzt abrufen', aus: true, grund: 'Gerade ist kein Kanal dieses Talents abrufbar: nicht verbunden, ohne Zugang, Talent archiviert oder Pause nach einer Abrufgrenze der Plattform.' }
      : { typ: 'aktion', text: 'Daten jetzt abrufen', aktion: 'tl_daten_abrufen', werte: { id: String(id) } };
  perf.inhalt = (Array.isArray(perf.inhalt) ? perf.inhalt : []).concat([knopf]);
  perf.info = [].concat(perf.info || [], [INFO]);
}
return aus.map(json => ({ json }));
};
// ===== Schritt: Content-Seite und Kacheln (Plan 62; Eingabe: Daten jetzt abrufen) =====
SCHRITT["Content-Seite und Kacheln"] = async ($input, $) => {
// Content-Seite und Kacheln (ALLY 25, Plan 62, Talent-Profil fertig; Entscheidungen Stefan über den Koordinator 01.11.2026):
// 1. T7 (01.11.2026, 15:17 „Kachel-Layout ist nicht vollständig“): „Aufgaben, Termine und Erinnerungen“ ist eine feste Kachel (Regel festeKacheln der Web-App). „Neu“ lag
//    im offenen Abschnitt hinter einem Knopf (Regel formularKnopf); in der Kachel öffnet „Neu“ dasselbe Formular als Fenster – wie „Notiz anlegen“ in der Kachel
//    „Daten und Notizen“. Felder, Aktion (kp_aufgabe_neu) und Knopf „Anlegen“ unverändert; der Knopf steht an der Liste.
// 2. P3 (21.10.2026, 14:18): eigene Content-Seite = Talent-Profil mit content=1: nur der Abschnitt „Content“ wie im Profil (Galerie/Tabelle, Format, Sortierung,
//    Blättern, Verfolgung, i), Krümelpfad Startseite › Dashboard › Name › Content. Vom Kopf bleibt nur der Filter „Account“ (wirkt auf die Beiträge); Zeitraum und
//    manuelle Daten wirken auf den Content nicht und bleiben nur in der Adresse (zurück zum Profil mit denselben Filtern).
// 3. Punkt 6 (Migration 196; Konzept Mediakit „Entscheidung“ Stefan 01.11.2026): Kachel „Mediakit“ = das selbst gestaltete Mediakit (PDF): Anzeige in der Kachel
//    (eingebettet über die Seite datei mit ta und ansehen=1), „Herunterladen“, hochladen bzw. ersetzen (mk_hochladen), Link zum Teilen erstellen, neu erstellen, widerrufen
//    (mk_link, mk_link_weg; Adresse nur einmal nach dem Erstellen). Ändern nur, wer das Talent verwaltet (talents_mediakit_ui, darf). Keine KI.
const aus = $input.all().map(x => x.json);
const E = $('Start').first().json;
const P = E.parameter || {};
const T = ($('Daten laden').first().json || {}).t || {};
const s = v => String(v ?? '');
const L = x => Array.isArray(x) ? x : [];
const id = Number((T.talent || {}).id);
const filter = {}; for (const k of ['zeitraum', 'von', 'bis', 'kanal', 'manuell']) if (P[k]) filter[k] = s(P[k]);
const res = [];
for (const j of aus) {
  const I = j && j.inhalt, S = I && I.seite;
  // nur das Profil selbst (mit Avatar; nicht Einstellungsseite, Beitrag, Werkzeug oder Fehlerseite)
  if (!S || typeof S !== 'object' || S.schluessel !== 'talent' || !S.avatar || S.zustand_teil === 'einstellungen' || T.ok !== true || !(id > 0) || !Array.isArray(I.abschnitte)) { res.push(j); continue; }
  const au = I.abschnitte.find(a => a && a.id === 'aufgaben');
  const fi = au && Array.isArray(au.inhalt) ? au.inhalt.findIndex(b => b && b.typ === 'formular' && b.id === 'aufgabe-neu') : -1;
  if (fi >= 0) {
    const fo = au.inhalt[fi], titel = s(fo.titel) || 'Neu';
    au.inhalt.splice(fi, 1, { typ: 'aktion', text: titel, fenster: 'aufgabe-neu' });
    I.fenster = L(I.fenster).concat([{ id: 'aufgabe-neu', art: 'dialog', titel, inhalt: [Object.assign({}, fo, { titel: undefined,
      knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }].concat(L(fo.knoepfe)) })] }]);
  }
  let MK = null;
  try { const x = ($('Daten laden').first().json || {}).mk; MK = x && x.ok === true ? x : null; } catch (e) { MK = null; }
  if (MK && !I.abschnitte.some(a => a && a.id === 'mediakit')) {
    const D0 = MK.datei && /^[0-9]{1,15}$/.test(s(MK.datei.id)) ? MK.datei : null, LK = MK.link || {};
    const datei = p => ({ seite: 'datei', parameter: Object.assign({ ta: s(D0.id), t: String(id) }, p || {}) });
    const inhalt = [];
    if (D0) inhalt.push({ typ: 'paare', eintraege: [{ label: 'Datei', wert: s(D0.name) }, { label: 'Stand', wert: [s(D0.stand), s(D0.von)].filter(Boolean).join(' · ') }] },
      { typ: 'pdf', titel: 'Mediakit von ' + s(S.titel), ziel: datei({ ansehen: '1' }) }, { typ: 'aktion', text: 'Herunterladen', ziel: datei() });
    else inhalt.push({ typ: 'text', ton: 'grau', text: 'Noch kein Mediakit hochgeladen.' });
    if (D0 && LK.aktiv === true) inhalt.push({ typ: 'text', text: 'Link zum Teilen aktiv seit ' + s(LK.seit) + ' · ' + (Number(LK.abrufe) || 0) + (Number(LK.abrufe) === 1 ? ' Abruf' : ' Abrufe') });
    if (MK.darf === true) {
      if (D0 && LK.aktiv === true) inhalt.push({ typ: 'aktion', text: 'Neuen Link erstellen', aktion: 'mk_link', werte: { talent_id: String(id) }, frage: 'Neuen Link erstellen? Der bisherige Link gilt dann nicht mehr.' },
        { typ: 'aktion', text: 'Link widerrufen', aktion: 'mk_link_weg', werte: { talent_id: String(id) }, frage: 'Link widerrufen? Wer ihn hat, sieht das Mediakit dann nicht mehr.' });
      else if (D0 && MK.adresse === true) inhalt.push({ typ: 'aktion', text: 'Link zum Teilen erstellen', aktion: 'mk_link', werte: { talent_id: String(id) } });
      inhalt.push({ typ: 'formular', id: 'mediakit', aktion: 'mk_hochladen', datei: true, werte: { talent_id: String(id) },
        felder: [{ typ: 'datei', name: 'datei', label: D0 ? 'Neue Fassung (PDF)' : 'Mediakit (PDF)', accept: 'application/pdf', pflicht: true, breite: 'voll' }], knoepfe: [{ text: D0 ? 'Ersetzen' : 'Hochladen' }] });
    }
    I.abschnitte.push({ id: 'mediakit', titel: 'Mediakit', zahl: D0 ? s(D0.stand) : '', offen_standard: false, kachel_aktion: 'Anzeigen',
      info: 'Das Mediakit gestalten Agentur oder Talent selbst (PDF); Ally erzeugt keins. Ally legt es im Speicherort der Talents ab (Ordner „Mediakits“) und zeigt es hier. „Ersetzen“ lädt eine neue Fassung hoch, die vorige Datei bleibt im Speicherort. Der Link zum Teilen zeigt das aktuelle Mediakit ohne Anmeldung, auch nach dem Ersetzen; er wird nur beim Erstellen angezeigt, „Link widerrufen“ macht ihn ungültig. Das Talent kann sein Mediakit im Talent-Bereich selbst hochladen.',
      inhalt });
  }
  if (s(P.content) !== '1') { res.push(j); continue; }
  const con = I.abschnitte.find(a => a && a.id === 'content');
  if (!con) { res.push(j); continue; }
  const name = s(S.titel);
  const krumen = L(S.krumen).slice(0, -1).concat([{ text: name, ziel: { seite: 'talent', parameter: Object.assign({ id: String(id) }, filter) } }, { text: 'Content' }]);
  const kf = S.filter && typeof S.filter === 'object' ? L(S.filter.felder).filter(f => f && f.name === 'kanal') : [];
  const seite = Object.assign({ schluessel: 'talent', art: S.art || 'funktion', titel: 'Content', beschreibung: name, avatar: S.avatar, krumen },
    kf.length ? { filter: { id: 'kanal', label: 'Account', felder: kf } } : {});
  const neu = { seite, abschnitte: [Object.assign({}, con, { offen_standard: true })], fenster: L(I.fenster) };
