  res.push(Object.assign({}, j, { inhalt: neu }));
}
return res.map(json => ({ json }));
};
for (const [name, ein] of [["Werkzeug-Links", "Seite beschreiben"], ["Download-Links", "Reports laden"], ["Datenimport-Link", "Download-Links"], ["Kopf-Metazeile", "Datenimport-Link"], ["Content-Galerie", "Kopf-Metazeile"], ["Profil wie ALLY 8", "Beitrag laden"], ["Links in neuem Tab", "Profil wie ALLY 8"], ["Verbindungen in Einstellungen", "Links in neuem Tab"], ["Einstellungen des Talents", "Verbindungen in Einstellungen"], ["Daten jetzt abrufen", "Einstellungen des Talents"], ["Content-Seite und Kacheln", "Daten jetzt abrufen"]]) {
  const r = await SCHRITT[name](als(eingabe(ein)), $merk);
