-- Papierkorb laden (ALLY 25, Migration 130): Einträge dieses Talents im Papierkorb, nur auf der Unterseite papierkorb=1 (talents_profil_pk_liste prüft Sitzung,
-- Sichtbarkeit und Rechte je Eintrag). Nur lesend. $1 Sitzung, $2 Talent, $3 Unterseite ('1' oder leer).
SELECT CASE WHEN $3::text = '1' AND $2::text ~ '^[0-9]{1,9}$' THEN talents_profil_pk_liste($1::text, CASE WHEN $2::text ~ '^[0-9]{1,9}$' THEN $2::text::integer END) END AS pk;

