// Talent-Profil mit Papierkorb (ALLY 25, Migration 130, E13 „Löschen = Papierkorb“; Entscheidungen des Koordinators 24.10.2026).
// Ergänzt das Profil, ohne die Knoten davor zu ändern (Muster wie „Marketing (Papierkorb)“, Migration 133):
//   Talent: „Archivieren“ heißt „In den Papierkorb“, „Reaktivieren“ heißt „Wiederherstellen“, die Marke „archiviert“ heißt „im Papierkorb“.
//   Unterobjekte: „Löschen“ bei Aufgaben/Terminen/Erinnerungen und Notizen heißt „In den Papierkorb“ (wie „Papierkorb: Löschen umbenennen“).
//   Knopf „Papierkorb“ im Kopf ohne Zähler (E9). Unterseite papierkorb=1: Einträge dieses Talents im Papierkorb (talents_profil_pk_liste, nur mit Recht)
//   mit „Wiederherstellen“ und „Endgültig löschen“, oben „Papierkorb leeren“ (genau die angezeigten, höchstens 1000); 10 je Seite (E8); nur der Papierkorb.
const E = $('Start').first().json;
const P = E.parameter || {};
const PL = ($input.first().json || {}).pk || null;
const LI = x => Array.isArray(x) ? x : [];
const s0 = v => String(v ?? '');
const JE = 10, MAX = 1000;
const LEER = 'Das lässt sich nicht rückgängig machen.';
const id = /^[0-9]{1,9}$/.test(s0(P.id)) ? s0(P.id) : '';
const FRAGE = { tn_loeschen: 'Notiz in den Papierkorb legen? Im Papierkorb kannst du sie wiederherstellen.' };
const TEXTE = { 'Für archivierte Talents lässt sich der Ally-Chat nicht einschalten.': 'Für Talents im Papierkorb lässt sich der Ally-Chat nicht einschalten.' };
const geh = x => {
  if (Array.isArray(x)) { x.forEach(geh); return; }
  if (!x || typeof x !== 'object') return;
  if (x.aktion === 'tn_loeschen' || x.aktion === 'kp_aufgabe_loeschen') {
    if (x.text === 'Löschen') x.text = 'In den Papierkorb';
    x.frage = x.aktion === 'tn_loeschen' ? FRAGE.tn_loeschen
      : s0(x.frage || 'Eintrag löschen?').replace(/ löschen\?$/, ' in den Papierkorb legen?') + ' Im Papierkorb kannst du den Eintrag wiederherstellen.';
  }
  if (typeof x.text === 'string' && TEXTE[x.text]) x.text = TEXTE[x.text];
  for (const k of Object.keys(x)) geh(x[k]);
};
const blatt = n => { const s = Math.max(1, Number((E.seiten || {})['talent-papierkorb']) || 1); return Math.min(s, Math.max(1, Math.ceil(n / JE))); };

return $('Testdaten kennzeichnen').all().map(it => {
  const j = it.json || {};
  const I = j.inhalt, S = I && I.seite;
  // nur das Profil selbst (mit Avatar); Fehlerseiten bleiben unverändert
  if (!S || typeof S !== 'object' || S.schluessel !== 'talent' || !S.avatar || !id) return { json: j };
  const name = s0(S.titel);
  for (const a of LI(S.aktionen)) {
    if (a && a.aktion === 'tl_talent_archivieren') {
      a.text = 'In den Papierkorb';
      a.frage = name + ' in den Papierkorb legen? Die Zahlen bleiben erhalten, es werden keine neuen abgerufen, offene Einladungslinks gelten nicht mehr. '
        + 'Im Papierkorb der Talents kannst du es wiederherstellen.';
    }
    if (a && a.aktion === 'tl_talent_reaktivieren') {
      a.text = 'Wiederherstellen';
      a.frage = name + ' wiederherstellen? Das Talent ist dann wieder aktiv. Für neue Verbindungen braucht es einen neuen Einladungslink.';
    }
  }
  if (S.meta && S.meta.marke && S.meta.marke.text === 'archiviert') S.meta.marke = { text: 'im Papierkorb', ton: 'warn' };
  if (typeof S.beschreibung === 'string') S.beschreibung = S.beschreibung.replace(/ · archiviert$/, ' · im Papierkorb');
  if (s0(P.papierkorb) === '1') {
    S.krumen = LI(S.krumen).slice(0, 2).concat([{ text: name, ziel: { seite: 'talent', parameter: { id } } }, { text: 'Papierkorb' }]);
    S.titel = 'Papierkorb';
    S.beschreibung = 'Gelöschte Aufgaben, Termine, Erinnerungen, Notizen, KI-Texte, Konzept-Ziele und Werte von ' + name + '. Im Papierkorb erinnert und zählt nichts.';
    delete S.hauptaktion; delete S.aktionen; delete S.filter; delete S.knoepfe; delete S.zahnrad; delete S.formular; delete S.speichern;
    const L = PL && PL.ok === true ? LI(PL.eintraege) : null;
    if (!L) {
      I.bloecke = [{ typ: 'hinweis', ton: 'warn', text: 'Der Papierkorb konnte nicht geladen werden. Bitte die Seite neu laden.' }];
      I.abschnitte = []; I.fenster = []; delete I.ueberblick;
      return { json: j };
    }
    if (L.length) S.hauptaktion = { text: 'Papierkorb leeren', art: 'neben', aktion: 'tp_papierkorb_leeren', werte: { ids: L.slice(0, MAX).map(v => s0(v.id)).join(',') },
      frage: 'Papierkorb endgültig leeren? ' + (L.length === 1 ? '„' + s0(L[0].titel) + '“ wird' : (L.length > MAX ? 'Die ersten 1000 von ' + L.length : 'Alle ' + L.length) + ' Einträge werden')
        + ' endgültig gelöscht. ' + LEER };
    const bl = blatt(L.length);
    I.abschnitte = [{ id: 'talent-papierkorb', titel: 'Im Papierkorb', zahl: String(L.length), offen_standard: true, inhalt: [{ typ: 'tabelle', id: 'talent-papierkorb', titel: 'Im Papierkorb',
      spalten: [{ schluessel: 'art', titel: 'Art' }, { schluessel: 'titel', titel: 'Eintrag' }, { schluessel: 'geloescht', titel: 'Gelöscht' }, { schluessel: 'aktion', titel: 'Aktion' }],
      zeilen: L.slice((bl - 1) * JE, bl * JE).map(v => ({ zellen: { art: s0(v.art_text), titel: v.kampagne ? { text: s0(v.titel), neben: 'Kampagne: ' + s0(v.kampagne) } : s0(v.titel),
        geloescht: v.geloescht_von ? { text: s0(v.geloescht), neben: s0(v.geloescht_von) } : s0(v.geloescht),
        aktion: { aktionen: [
          { text: 'Wiederherstellen', aktion: 'tp_papierkorb_wiederherstellen', werte: { id: s0(v.id) }, frage: s0(v.art_text) + ' „' + s0(v.titel) + '“ wiederherstellen?' },
          { text: 'Endgültig löschen', aktion: 'tp_papierkorb_endgueltig', werte: { id: s0(v.id) }, frage: s0(v.art_text) + ' „' + s0(v.titel) + '“ endgültig löschen? ' + LEER }] } } })),
      seite: bl, je_seite: JE, gesamt: L.length, leer: 'Der Papierkorb ist leer.' }] }];
    I.fenster = [];
    delete I.bloecke; delete I.ueberblick;
    return { json: j };
  }
  geh(I);
  S.knoepfe = LI(S.knoepfe).filter(k => !(k && k.text === 'Papierkorb')).concat([{ text: 'Papierkorb', ziel: { seite: 'talent', parameter: { id, papierkorb: '1' } } }]);
  return { json: j };
});

// Papierkorb: Löschen umbenennen (ALLY 24 und 25, Migration 130, E13 „Löschen = Papierkorb“; Koordinator 24.10.2026).
