  }
  if (typeof x.text === 'string' && TEXTE[x.text]) x.text = TEXTE[x.text];
  for (const k of Object.keys(x)) geh(x[k]);
};
return $input.all().map(it => { const j = it.json || {}; geh(j.inhalt); return { json: j }; });

