-- Einladung-Versand laden (ALLY 25, Plan 57, Migration 192): Stand, Grenzen, sendefähige Postfächer und Vorschauen für das Fenster „Einladung für …“
-- je Talent (talent_einladung_fenster prüft Sitzung, Sichtbarkeit und Recht wie „Neuer Link“). Nur lesend. $1 Sitzung, $2 Talents (Komma-Liste, leer = nichts).
SELECT talent_einladung_fenster($1::text, $2::text) AS ev;

parameters.jsCode:
// Einladung per Mail (ALLY 25, Plan 57, Migration 192; Konzept Einladungsmail Teil 2, Entscheidungen Stefan 01.11.2026): ergänzt das vorhandene Fenster
// „Einladung für …“ um die drei Wege, ohne die Knoten davor zu ändern: „Als Entwurf ablegen“ (wie Korrespondenz › Mail-Entwurf anlegen), „Über den Absender für
// Systemnachrichten senden“ und „Über mein Postfach senden“ (eigene und freigeschaltete gemeinsame Postfächer mit eingerichtetem Versand, Standard-Postfach zuerst).
// Daten aus „Einladung-Versand laden“ (talent_einladung_fenster): Stand, Sperren und Grenzen, sendefähige Postfächer, Vorschauen der Mail; Rechte und Prüfung in der
// Datenbank (beim Senden noch einmal). Nur vorhandene Muster: Unterüberschrift mit i, graue Zeile für Stand und Sperren, Formulare mit Titel und i, Feld mailvorschau,
// Auswahl mit zeigen_wenn, Rückfrage (frage) mit benanntem Knopf. Gesendet wird über me_anlegen (ALLY 20 „Werkzeug-Felder“ → talents_mail_entwurf_anlegen mit versand).
const aus = $('Talent-Profil (Papierkorb)').all().map(x => x.json);
let EV = {};
try { EV = ($input.first().json || {}).ev || {}; } catch (e) { EV = {}; }
if (!EV || typeof EV !== 'object' || Array.isArray(EV)) EV = {};
const L = x => Array.isArray(x) ? x : [];
const s = v => String(v ?? '');
const P0 = (($('Start').first().json || {}).parameter) || {};
const TID = /^[0-9]{1,9}$/.test(s(P0.id)) ? s(P0.id) : '';
const opt = (w, t) => ({ wert: s(w), text: s(t) });
const pfText = p => s(p.adresse);   // nur die Adresse: am Handy ganz sichtbar (Prüfliste 16)
const ALT = 'Es wird nichts automatisch verschickt: Link oder Text kopieren und dem Talent schicken.';
const NEU = 'Link oder Text kopieren und dem Talent schicken oder unten per Mail senden. Ally verschickt nur, wenn du dort einen Weg wählst und bestätigst.';
const vorschau = (name, v, extra) => Object.assign({ typ: 'mailvorschau', name, label: 'Vorschau', von: s(v.von), an: s(v.an), betreff: s(v.betreff), html: s(v.html) }, extra || {});
for (const j of aus) {
  const I = j && j.inhalt;
  if (!I || typeof I !== 'object' || !Array.isArray(I.fenster)) continue;
  for (const F of I.fenster) {
    const m = /^einladung(?:-([0-9]{1,9}))?$/.exec(s(F && F.id));
    if (!m || !Array.isArray(F.inhalt)) continue;
    const tid = m[1] || TID, V = EV[tid];
    if (!tid || !V || V.darf !== true) continue;
    for (const b of F.inhalt) if (b && b.typ === 'formular') for (const f of L(b.felder)) if (f && f.name === 'link') f.info = L(f.info).map(x => x === ALT ? NEU : x);
    const sfx = '-' + tid, an = s(V.an);
    const neu = [{ typ: 'unterueberschrift', text: 'Einladung per Mail',
      info: 'Ally schickt die Einladung im Corporate Design mit dem Knopf „Accounts verbinden“. Ob sie rausging, steht danach beim Talent unter Kommunikation › Korrespondenz.' }];
    if (V.letzter) neu.push({ typ: 'text', ton: 'grau', text: s(V.letzter) });
    const E = V.entwurf || {}, EP = L(E.postfaecher).filter(p => p && p.adresse);
    if (E.moeglich === true && EP.length) neu.push({ typ: 'formular', id: 'einladung-entwurf' + sfx, titel: 'Als Entwurf ablegen',
      info: 'Die Mail liegt danach im Entwurfsordner des gewählten Postfachs. Abschicken musst du sie selbst.', aktion: 'me_anlegen',
      werte: { talent_id: tid, art: 'einladung', versand: 'entwurf' },
      felder: [{ typ: 'auswahl', name: 'postfach', label: 'Postfach', wert: s((EP.find(p => p.standard === true) || EP[0]).adresse), optionen: EP.map(p => opt(p.adresse, pfText(p))) }],
      knoepfe: [{ text: 'Entwurf ablegen', art: 'neben' }] });
    else if (E.moeglich === true) neu.push({ typ: 'text', ton: 'grau', text: 'Als Entwurf: kein Postfach mit eingeschalteten Mail-Entwürfen.' });
    if (V.sperre) neu.push({ typ: 'text', ton: 'grau', text: s(V.sperre) });
    else {
      const S = V.system || {};
      if (S.moeglich === true && S.vorschau) neu.push({ typ: 'formular', id: 'einladung-system' + sfx, titel: 'Über den Absender für Systemnachrichten senden',
        info: 'Ally schickt die Mail im Namen der Firma. Sie geht in etwa einer Minute raus.', aktion: 'me_anlegen',
        werte: { talent_id: tid, art: 'einladung', versand: 'system' }, felder: [vorschau('vorschau_system', S.vorschau)],
        frage: 'Einladung jetzt an ' + an + ' senden? Absender: ' + s(S.vorschau.von) + '. Die Mail geht in etwa einer Minute raus.',
        knoepfe: [{ text: 'Jetzt senden', art: 'neben' }] });
      else neu.push({ typ: 'text', ton: 'grau', text: s(S.grund || 'Kein Absender für Systemnachrichten eingerichtet (Einstellungen › Postfächer, nur Admin).') });
      const PF = L((V.postfach || {}).postfaecher).filter(p => p && p.adresse && p.vorschau);
      if (PF.length) {
        const felder = PF.length > 1 ? [{ typ: 'auswahl', name: 'postfach', label: 'Postfach', wert: s(PF[0].adresse), optionen: PF.map(p => opt(p.adresse, pfText(p))) }] : [];
        PF.forEach((p, i) => felder.push(vorschau('vorschau_' + i, p.vorschau, PF.length > 1 ? { zeigen_wenn: { feld: 'postfach', werte: [s(p.adresse)] } } : {})));
        neu.push({ typ: 'formular', id: 'einladung-postfach' + sfx, titel: 'Über mein Postfach senden',
          info: 'Ally schickt die Mail sofort über das Postfach, mit deinem Namen und deiner Signatur.', aktion: 'me_anlegen',
          werte: Object.assign({ talent_id: tid, art: 'einladung', versand: 'postfach' }, PF.length === 1 ? { postfach: s(PF[0].adresse) } : {}), felder,
          frage: PF.length === 1 ? 'Einladung jetzt über ' + s(PF[0].adresse) + ' an ' + an + ' senden?' : 'Einladung jetzt über das gewählte Postfach an ' + an + ' senden?',
          knoepfe: [{ text: 'Über mein Postfach senden', art: 'neben' }] });
      } else neu.push({ typ: 'text', ton: 'grau', text: s((V.postfach || {}).grund || 'Für dich ist kein Postfach mit Versand eingerichtet (Einstellungen › Meine Postfächer, Abschnitt „Zugang und Versand“, „Versand erlauben“).') });
    }
    // nach „Im Mailprogramm öffnen“ (sonst nach dem ersten Formular), vor den Textaktionen („Zum Talent“, „Neuer Link“)
    let pos = -1;
    F.inhalt.forEach((b, i) => { if (b && b.mailto) pos = i; });
    if (pos < 0) pos = F.inhalt.findIndex(b => b && b.typ === 'formular');
    F.inhalt.splice(pos + 1, 0, ...neu);
  }
}
// Migration 200 (Fehler Nr. 40, Stefan 02.11.2026 16:44 „b“; Korrektur 03.11.2026 09:23: nur Themen, die der Manager betreut): Freigabe je Eintrag für den
// Talent-Bereich. Ergänzt das fertige Profil, ohne die Knoten davor zu ändern. Daten aus „Abruf-Stand“ (fg = talent_freigaben_ui: je Art Eintrag -> an; darf = Recht
// „Talent-Zugang und Talent-Bereich einstellen“). In den Kacheln Kampagnen, Strategie und Kommunikation, Reports, Mediakit, Daten und Notizen je Eintrag die Marke
// „für Talent sichtbar“ (in Daten und Notizen nur Notizen); im Fenster des Eintrags (Notizen: vorhandenes Fenster; sonst ein kleines Fenster „Sichtbarkeit“) der Schalter „Für das Talent sichtbar“ als
// sofort gespeicherte Aktion tz_fuer_talent (talent_id, art, eintrag, an; Rechte prüft talent_fuer_talent_setzen). Ohne Recht nur die Marke. Zuordnung immer über die
// ID des Eintrags (aus Ziel oder Aktion der Zeile); fehlt sie in der Zeile, nur bei genau einem passenden Eintrag (gleiche Texte), sonst ohne Marke und Schalter.
// Aufgaben, Termine, Erinnerungen, Verbindungen und manuell erfasste Werte haben keine Freigabe.
{
  let FG = null;
  try { const x = ($('Abruf-Stand').first().json || {}).fg; FG = x && x.ok === true ? x : null; } catch (e) { FG = null; }
  const D0 = $('Daten laden').first().json || {};
  const T0 = D0.t || {};
  let RB = [];
  try { RB = L((($('Reports laden').first().json || {}).b || {}).zeilen).filter(x => x && /^[0-9]{1,12}$/.test(s(x.id))); } catch (e) { RB = []; }
  const MARKE = { text: 'für Talent sichtbar', ton: 'ok' };
  const INFO = 'Freigegebene Einträge sieht das Talent in seinem Bereich. Neue Einträge sind zunächst nicht freigegeben; was das Talent selbst hochlädt, sieht es ohne Freigabe.';
  for (const j of (FG ? aus : [])) {
    const I = j && j.inhalt;
    if (!I || typeof I !== 'object' || !Array.isArray(I.abschnitte) || !I.seite || I.seite.schluessel !== 'talent') continue;
    const tid = s(FG.talent_id);
    I.fenster = L(I.fenster);
    const AB = id => I.abschnitte.find(a => a && a.id === id);
    const an = (art, eid) => { const m = FG[art] || {}, v = m[s(eid)]; return v === true || (v && typeof v === 'object' && v.an === true); };
    // Schalter: Stand und eine Aktion zum Umschalten (sofort gespeichert), nur mit Recht; selbst = vom Talent selbst angelegt (sichtbar ohne Freigabe)
    const schalter = (art, eid, ein, extra) => {
      const b = [{ typ: 'unterueberschrift', text: 'Für das Talent sichtbar', info: INFO },
        { typ: 'paare', eintraege: [{ label: 'Für das Talent sichtbar', wert: ein ? 'ja' : extra && extra.selbst ? 'ja (selbst angelegt)' : 'nein' }] }];
      if (extra && extra.grund) b.push({ typ: 'text', ton: 'grau', text: extra.grund });
      else if (FG.darf === true) b.push({ typ: 'aktion', text: ein ? 'Für das Talent ausblenden' : 'Für das Talent sichtbar machen', aktion: 'tz_fuer_talent', art: 'neben',
        werte: Object.assign({ talent_id: tid, art, an: ein ? '0' : '1' }, eid !== null ? { eintrag: s(eid) } : {}) });
      return b; };
    const kleinesFenster = (art, eid, titel, ein, extra) => { const fid = 'tf-' + art + '-' + s(eid);
      if (!I.fenster.some(f => f && f.id === fid)) I.fenster.push({ id: fid, art: 'dialog', titel: 'Sichtbarkeit für das Talent', untertitel: titel, inhalt: schalter(art, eid, ein, extra) });
      return fid; };
    const zelleMarke = (z, k) => { if (!z || !z.zellen) return; const c = z.zellen[k];
      z.zellen[k] = c && typeof c === 'object' ? Object.assign({}, c, { marke: MARKE }) : { text: s(c), marke: MARKE }; };
    const zelleAktion = (z, k, fid) => { if (!z || !z.zellen) return; const c = z.zellen[k], a = { text: 'Sichtbarkeit', fenster: fid };
      z.zellen[k] = c && typeof c === 'object' ? Object.assign({}, c, { aktionen: L(c.aktionen).concat(c.aktion ? [c.aktion] : [], [a]), aktion: undefined }) : { text: s(c), aktion: a }; };
    // genau ein Eintrag mit dieser Kennung (Texte der Zeile), sonst keiner
    const einzig = (liste, sig, wert) => { const x = liste.filter(e => sig(e) === wert); return x.length === 1 ? x[0] : null; };
    const zt = c => c && typeof c === 'object' ? s(c.text) : s(c);
    // Kampagnen (Teilnahme dieses Talents): Marke am Titel, Schalter im Fenster „Sichtbarkeit“
    const ka = AB('kampagnen'), tk = ka ? L(ka.inhalt).find(b => b && b.typ === 'tabelle' && b.id === 'kampagnen') : null;
    for (const z of (tk ? L(tk.zeilen) : [])) {
      const c = z && z.zellen && z.zellen.titel, kid = c && c.ziel && c.ziel.parameter ? s(c.ziel.parameter.kampagne) : '';
      if (!/^[0-9]{1,9}$/.test(kid) || !Object.prototype.hasOwnProperty.call(FG.kampagne || {}, kid)) continue;
      const ein = an('kampagne', kid); if (ein) zelleMarke(z, 'titel');
      zelleAktion(z, 'status', kleinesFenster('kampagne', kid, s(c.text), ein));
    }
    // Reports: ID aus „Herunterladen“ (tr), sonst Titel und Erstellt wie in „Seite ergänzen“; nur Reports allein über dieses Talent lassen sich freigeben
    const rp = AB('reports'), tr = rp ? L(rp.inhalt).find(b => b && b.typ === 'tabelle' && b.id === 'reports') : null;
    const rSig = x => s(x.titel) + '|' + ([x.erstellt_text, x.erstellt_von_name].filter(Boolean).join(' · ') || '–');
    for (const z of (tr ? L(tr.zeilen) : [])) {
      const c = (z && z.zellen) || {}, d = c.datei && typeof c.datei === 'object' && c.datei.ziel && c.datei.ziel.parameter ? s(c.datei.ziel.parameter.tr) : '';
      const r0 = /^[0-9]{1,12}$/.test(d) ? RB.find(x => s(x.id) === d) || { id: d, titel: zt(c.titel) } : einzig(RB, rSig, zt(c.titel) + '|' + zt(c.erstellt));
      if (!r0) continue;
      const bid = s(r0.id), v = (FG.bericht || {})[bid]; if (!v) continue;
      if (v.an === true) zelleMarke(z, 'titel');
      zelleAktion(z, 'erstellt', kleinesFenster('bericht', bid, s(r0.titel), v.an === true,
        v.moeglich === true || v.an === true ? null : { grund: 'Freigeben lassen sich nur Reports allein über dieses Talent, ohne Vergleich mit anderen Talents und ohne Kampagnen-Ergebnis.' }));
    }
    // Daten und Notizen: nur Notizen (ID aus „Bearbeiten“ bzw. „Löschen“, sonst Datum, Von und Text eindeutig; Schalter im Fenster notiz-<id> oder „Sichtbarkeit“).
    // Manuell erfasste Werte haben keine Freigabe (Stefan 03.11.2026 09:48), das Talent sieht sie immer.
    const da = AB('daten');
    if (da && Array.isArray(da.inhalt)) {
      const NL = L((D0.n || {}).notizen), tn = da.inhalt.find(b => b && b.typ === 'tabelle' && b.id === 'notizen');
      const nSig = x => s(x.datum) + '|' + s(x.autor) + '|' + s(x.text);
      for (const z of (tn ? L(tn.zeilen) : [])) {
        const c = (z && z.zellen) || {}, ak = c.aktion && typeof c.aktion === 'object' ? c.aktion : {};
        const fm = /^notiz-([0-9]{1,18})$/.exec(s(ak.fenster)), wid = ak.aktion && ak.aktion.werte ? s(ak.aktion.werte.id) : '';
        const n0 = fm ? { id: fm[1] } : /^[0-9]{1,18}$/.test(wid) ? { id: wid } : einzig(NL, nSig, zt(c.datum) + '|' + zt(c.autor) + '|' + zt(c.text));
        const nid = n0 ? s(n0.id) : ''; if (!/^[0-9]{1,18}$/.test(nid) || !Object.prototype.hasOwnProperty.call(FG.notiz || {}, nid)) continue;
        const ein = an('notiz', nid); if (ein) zelleMarke(z, 'text');
        const fe = I.fenster.find(f => f && f.id === 'notiz-' + nid);
        if (fe && Array.isArray(fe.inhalt)) fe.inhalt.push(...schalter('notiz', nid, ein));
        else zelleAktion(z, 'aktion', kleinesFenster('notiz', nid, zt(c.datum), ein));
      }
    }
    // Strategie und Kommunikation: Content-Strategien des Talents mit Marke und Schalter
    const ws = AB('werkzeuge'), KZ = L(FG.konzept);
    if (ws && Array.isArray(ws.inhalt) && KZ.length) ws.inhalt.push({ typ: 'unterueberschrift', text: 'Content-Strategien für das Talent', info: INFO },
      { typ: 'liste', eintraege: KZ.map(k => Object.assign({ fett: s(k.text), text: s(k.status_text), aktion: { text: 'Sichtbarkeit', fenster: kleinesFenster('konzept', k.id, s(k.text), k.an === true) } },
        k.an === true ? { marke: MARKE } : {})) });
    // Mediakit: ein Eintrag je Talent; selbst hochgeladen = sichtbar ohne Freigabe; ein neu hochgeladenes Mediakit des Managers ist wieder nicht freigegeben
    const mk = AB('mediakit'), MF = FG.mediakit;
    if (mk && Array.isArray(mk.inhalt) && MF && typeof MF === 'object') {
      if (MF.an === true || MF.selbst === true) mk.zahl = [s(mk.zahl), MARKE.text].filter(Boolean).join(' · ');
      mk.inhalt.push(...schalter('mediakit', null, MF.an === true, { selbst: MF.selbst === true }));
    }
  }
}
return aus.map(json => ({ json }));

// Korrespondenz: Versand (ALLY 25, Plan 57, Migration 192): Talent-Profil › Kommunikation › Korrespondenz. Die Tabelle der Mail-Entwürfe zeigt jetzt auch gesendete
// Einladungen (talents_mail_daten → talent_mail_verlauf: über ein Postfach und über den Absender für Systemnachrichten). Nur Texte von Abschnitt und Tabelle;
// ohne „Werkzeug beschreiben“ zu ändern. Andere Seiten unverändert.
const aus = $input.all().map(x => x.json);
for (const j of aus) {
  const I = j && j.inhalt;
  if (!I || typeof I !== 'object' || !Array.isArray(I.abschnitte) || !I.abschnitte.some(a => a && a.id === 'entwurf-neu')) continue;
  const a = I.abschnitte.find(x => x && x.id === 'entwuerfe');
  if (!a) continue;
  a.titel = 'Entwürfe und Versand';
  a.info = 'Abgelegte Mail-Entwürfe und gesendete Einladungen zu diesem Talent, mit Stand.';
  for (const b of Array.isArray(a.inhalt) ? a.inhalt : []) if (b && b.typ === 'tabelle' && b.id === 'entwuerfe') { b.titel = 'Entwürfe und Versand'; b.leer = 'Noch keine Entwürfe und keine gesendeten Einladungen.'; }
}
return aus.map(json => ({ json }));

// Audience-Grund (ALLY 25, Fehler Nr. 28, Stefan 02.11.2026): die Kachel Audience nennt den Grund, wenn Angaben fehlen – Instagram liefert die Zielgruppe
// erst ab 100 Followern. Ohne Angaben: Grund und Follower laut Überblick; mit Angaben: verbundene Instagram-Kanäle ohne Angaben mit Namen.
// Ergänzt „Seite ergänzen“, ohne es zu ändern. „Daten jetzt abrufen“ holt die Zielgruppe mit (TALENTS 3, Migration 194).
const T = ($('Daten laden').first().json || {}).t || {};
const s = v => String(v ?? '');
const L = x => Array.isArray(x) ? x : [];
const ZG = L(T.zielgruppe);
const GRUND = 'Instagram zeigt die Audience erst ab 100 Followern.';
const fk = L(T.kennzahlen).find(k => k && k.schluessel === 'follower');
const mitDaten = new Set(ZG.map(g => s(g.kanal_id)));
const ohne = L(T.kanaele).filter(k => k && k.plattform === 'instagram' && k.status === 'verbunden' && !mitDaten.has(s(k.kanal_id))).map(k => s(k.text || k.name)).filter(Boolean);
return $input.all().map(it => {
  const I = it.json && it.json.inhalt;
  const a = I && Array.isArray(I.abschnitte) ? I.abschnitte.find(x => x && x.id === 'audience') : null;
  if (!a || !Array.isArray(a.inhalt)) return it;
  if (!ZG.length) {
    const t = a.inhalt.find(b => b && b.typ === 'text');
    const zahl = fk && s(fk.text) && s(fk.text) !== '–' ? ' Follower laut Überblick: ' + s(fk.text) + '.' : '';
    if (t) t.text = 'Noch keine Angaben zur Audience. ' + GRUND + zahl;
  } else if (ohne.length) a.inhalt.push({ typ: 'text', ton: 'grau', text: 'Ohne Angaben: ' + ohne.join(', ') + '. ' + GRUND });
  return it;
});
